insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('HMB310H1', 'Laboratory in Neuroscience', '12L/36P', 'A laboratory course based on current research techniques for students in the Neuroscience program. Lab topics may include human brain imaging and disorders, electrophysiology, cell culture, and changes in gene expression during neuronal development. Labs start in the first week of term. (Lab Materials Fee: $67)', 'HMB311H1/  HMB312H1/  HMB314H1/  PSY359H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB200H1", "PSY290H1"]}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB311H1', 'Laboratory in Fundamental Genetics and its Applications', '12L/36P', 'A laboratory course based on current research techniques for students in the Fundamental Genetics and its Applications programs. Lab topics may include molecular biology and animal cell culture techniques, nutrigenomics; an overview of microarrays and a CRISPR module. Labs start in the first week of term. (Lab Materials Fee: $162)', 'HMB310H1/  HMB312H1/  HMB314H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "HMB201H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB312H1', 'Laboratory in Health and Disease', '12L/36P', 'A laboratory course based on current research techniques and topics which may include basic microbiology, molecular biology and animal cell culture techniques, immunocytochemistry, changes in gene expression, and histological techniques. Labs start in the first week of term. (Lab Materials Fee: $105)', 'HMB310H1/ HMB311H1/ HMB314H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB202H1", "HMB203H1", "HMB204H1"]}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB314H1', 'Laboratory in Human Biology', '12L/36P', 'Students analyze whole body, cellular, and molecular responses to stress. Techniques range from those standard in medical practice (e.g., fitness measures, blood pressure, lung function) to current research techniques (cell culture, changes in gene expression). Students gain technical and analytical skills as they work at the bench to design and carry out individual and group experiments. Labs start in the first week of term. (Lab Materials Fee: $61)', 'HMB310H1/  HMB311H1/  HMB312H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB320H1', 'Neuroanatomy', '24L/4T/10P', 'This is a rigorous, introductory course that addresses the structure of the vertebrate central nervous system with an emphasis on functional human neuroanatomy. It is designed for students who intend to continue with studies in the Neurosciences and related areas.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "PSL300H1", "HMB200H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB321H1', 'Topics in Genetics', '24L/12T', 'The overall theme of this course is human genetics in disease. Topics include the molecular basis of human disease, using model organisms to identify disease-related genes, and genetic counseling. Expert guest lectures from clinical and basic sciences as well as small group work in tutorials build in-depth understanding.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}]}'::jsonb),
    ('HMB322H1', 'Topics in Health & Disease', '24L/12T', 'Explore the scientific basis and interdisciplinary healthcare practices of several diseases (diseases vary by year). Discuss current issues related to the biology and the impact of these diseases.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB202H1", "HMB203H1", "HMB204H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, "PSL300H1"]}'::jsonb),
    ('HMB323H1', 'Global Health Research', '24L/12T', 'Health is a responsibility shared worldwide. Globalization of health has impacted biomedical research. Students will explore current global health research advances and build skills in the design and conduct of global health research studies.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB202H1", "HMB203H1", "HMB204H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}]}'::jsonb),
    ('HMB342H1', 'Epidemiology of Health & Disease', '24L/12T', 'This course engages students in the fundamental science of epidemiology applied to health and disease. After an introduction to various measures of health and disease, the scientific methods used to investigate, analyze, prevent and control health problems will be illustrated using social, biomedical and public health examples', 'HST373H1', 5, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["BIO120H1", "BIO130H1", "HST209H1"]}]}'::jsonb),
    ('HMB360H1', 'Neurogenomics', '24L/12T', 'This course covers two main themes: Emerging gene or cell-based therapies to treat neurological disorders and genome engineering tools and techniques to investigate both normal and abnormal brain function. Topics may include cell reprogramming & stem cell technologies, brain organoids & tissue engineering, emerging genome engineering approaches to treat neurodegenerative diseases and behavioural disorders, and optogenetics to probe neural circuit function. Tutorials emphasize critical analysis of primary research.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["HMB200H1", "HMB201H1"]}]}'::jsonb),
    ('HMB385H1', 'The Human Microbiome in Health & Disease', '24L/12T', 'The gut microbiome affects numerous aspects of human health and disease, from metabolic and neurodevelopmental disorders to cancer and host behaviour. This course explores the physiological role of the microbiome in human development, human disease, drug efficacy and drug resistance and the emerging gut microbiome as diagnostic and therapeutic target.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["HMB200H1", "HMB201H1", "HMB202H1", "HMB203H1", "HMB204H1"]}]}'::jsonb),
    ('HMB394Y0', 'International Research Project in Human Biology', null, 'Your individual, independent research project is supervised by a faculty member in an approved university. This unique opportunity to conduct a lab-based research project is open to students in any Human Biology program. Coordinated by Centre for International Experience. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 8.5, "department": null}]}'::jsonb),
    ('HMB395Y0', 'Summer Abroad Topics in Human Biology', '48L/48S', 'Topics in Human Biology for the Summer Abroad Program. Course topics, content, and instructor may vary from one year to another. More information about Human Biology and other course offerings can be obtained from the Summer Abroad website at https://summerabroad.utoronto.ca/. For students in any Human Biology Program.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HMB396Y0', 'International Research Project in Human Biology', null, 'Your individual, independent research project is supervised by a faculty member in an approved university. This unique opportunity to conduct a lab-based research project is open to students in any Human Biology program. Not eligible for CR/NCR option. Coordinated by Woodsworth College.', null, null, null::jsonb),
    ('HMB398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HMB399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HMB399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HMB401H1', 'Biomedical Advances & Technologies', '24L/12T', 'This course introduces life science students to biomedical advances and technologies in medicine, including drug patents, medical device implants, diagnostic and medical device software. Limitations of patent protection in commercializing medical products, and limitations to scalability may also be discussed. Specific topics vary from year to year and will be based on the course instructor''s area(s) of expertise.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB301H1", "HMB321H1", "HMB360H1", "BCH311H1", "CSB349H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('HMB402H1', 'Topics in Translational Medicine', '18L/6S', 'The bridge between basic scientific research and clinical practice integrates fundamental knowledge about molecular/cellular mechanisms and clinical disorders to increase the potential for new medical treatments, therapies and interventions as well as understanding of disease processes. Specific topics vary from year to year and will be based on the instructor''s area(s) of expertise.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "BCH210H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB302H1", "HMB321H1", "HMB322H1", "BCH311H1", "CSB349H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('HMB406H1', 'Health Care Ethics', '8L/16S', 'Since research involving human subjects lays the foundation for innovation in modern health care, this course examines health care ethics along a continuum from bench to bedside. Ethical issues are discussed in the context of specific cases involving human research, as well as contemporary clinical practice.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 0.5, "department": null}, {"operator": "OR", "items": ["HMB306H1", "PHL281H1"]}]}'::jsonb),
    ('HMB420H1', 'Seminar in Neurobiology of Behaviour', '12L/12S', 'This seminar course focuses on recent research into the neurobiology underlying human behaviour. A variety of normal and abnormal human behaviours are studied which may include: voluntary action; moral cognition; hedonism; aggression; mental health; addiction; the impact of the gut microbiome on brain development and health.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB200H1", "HMB300H1", {"operator": "OR", "items": ["HMB320H1", "ANA300Y1"]}]}'::jsonb),
    ('HMB421H1', 'Seminar in Fundamental Genetics and its Applications', '12L/12S', 'Theme based lecture and seminar course underlining current medical research in relation to the areas of genes and genetics. Topics vary yearly.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB201H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}]}'::jsonb),
    ('HMB422H1', 'Seminar in Health & Disease', '16L/8S', 'This course focuses on various medical research related to human disease. Topics vary based on course instructor''s area(s) of expertise.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", "PSL301H1", {"operator": "OR", "items": ["HMB302H1", "HMB322H1"]}]}'::jsonb),
    ('HMB423H1', 'Non-Communicable Diseases: A Global Health Challenge', '24L', 'This course explores the connection between biological processes involved in the development of non-communicable diseases that affect Canadians and the greater global community. Students will critically examine precursors of disease from early life throughout the life course to understand metabolic processes and disease etiology and their manifestation across populations against a backdrop of an everchanging sociocultural, geopolitical, and environmental climate. The course explores the intersection of biological factors and processes, and the evolution of chronic disease management alongside learning about the application of historical medical/public health practices. Students will also critically examine the intersection of biology and developmental determinants of health involved in the perpetuation of racial disparities of chronic disease and implications for effective population-level interventions and prevention efforts.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB203H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('HMB430H1', 'Trends in Neuroscience', '18L/6S', 'Current research covering the breadth of neuroscience is showcased by members of the Collaborative Program in Neuroscience. Topics vary yearly, but cover the spectrum from molecular through genetic, cellular, developmental, systems, behavioural and modelling. As well, approaches to studying neurodegenerative diseases and clinical neurophysiology are introduced.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB200H1", "CJH332H1", {"operator": "OR", "items": ["HMB320H1", "JHA410H1", "ANA300Y1"]}]}'::jsonb),
    ('HMB431H1', 'Innovation in Genome Engineering and Translational Research', '8L/16S', 'From bench to bedside, this seminar-based course explores innovation in research and technology and their application in the medical field. Special emphasis on innovative genetic engineering approaches used in combination with stem cell technologies to transform the field of personalized and regenerative medicine.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB301H1", "HMB360H1", "HMB321H1"]}]}'::jsonb),
    ('HMB432H1', 'Topics in Histology & Histopathology', '12L/12S', 'Lecture and seminar course emphasizing current research. Topics may include the digestive system, cardiovascular system, respiratory system, stem cells, and neoplasia. Topics vary depending on class interest.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB302H1", "HMB322H1"]}]}'::jsonb),
    ('HMB433H1', 'Topics in Global Health', '16L/8S', 'Seminar and theme based course examining the opportunity to apply basic knowledge of biological determinants of disease to designing health system interventions and informatics that can have a global impact in the near term.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB303H1", "HMB323H1"]}]}'::jsonb),
    ('HMB434H1', 'Complementary & Integrative Medicine', '20L/4S', 'Introduction to complementary and alternative medical therapies. Topics include, Traditional Chinese Medicine, Naturopathy, Ayurvedic, and Mind-Body Practices. Biological mechanisms will be emphasized and therapies will be critically analyzed from an evidence-based research perspective. Integrating alternative therapies into Western practices with a focus on personalized medicine will be discussed.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "BCH210H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB302H1", "HMB312H1", "HMB314H1", "HMB322H1", "HMB323H1", "HMB342H1"]}]}'::jsonb),
    ('HMB435H1', 'Selected Topics in Molecular Cell Biology', '16L/8S', 'Theme-based lecture and seminar course underlining current basic science research in the area of molecular and cell biology, focusing on cell migration and its relevance to human health and disease. Topics may focus on the impact of fundamental processes underlying the cell biology, physiology and pathophysiology of cell motility in a variety of systems (e.g. immune, nervous system, cancer context).', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('HMB437H1', 'The Biology of the Human Metallome', '24L', 'This course will discuss how heavy metals are integral to organ function through various biological pathways, the importance of metal regulation and control and its relationship with gene transcription. An introduction of metallo-therapeutics will also be featured, ranging from neurodegenerative therapies to cancer treatment.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, "BCH210H1"]}'::jsonb),
    ('HMB440H1', 'Dementia', '24L', 'This course, featuring a service-learning component, explores dementia. In patients with dementia, intellectual, social and occupational functioning deteriorate. The course addresses the multi-disciplinary aspects of dementia (clinical, genetic, molecular, social) with a focus on the most common cause of dementia, Alzheimer''s disease. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. The application will ask about motivation and/or relevant experience. Applications are received during priority course enrollment, and late applications considered if space remains. Specific application review and response dates will be available on the HMB Special Enrolment website. Applications will be assessed based on prerequisites, submitted answers to application prompts and cGPA. This course is open to all Human Biology students.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["HMB300H1", "HMB302H1", "HMB320H1", "HMB321H1", "ANA300Y1"]}]}'::jsonb),
    ('HMB441H1', 'Genetics of Human Disease', '24L', 'This advanced course aims to provide students with current, in-depth knowledge of the genetics of specific human diseases, including single gene (e.g., Huntington disease), multifactorial (e.g. Alzheimer''s disease), and non-Mendelian (e.g. mitochondrial DNA-related disease) disorders, and how the use of genetics to elucidate disease mechanisms can lead to treatments and personalized medicine in order to improve healthcare.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "BCH210H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["HMB302H1", "HMB321H1", "HMB322H1", "HMB360H1", "BCH311H1", "CSB349H1", "MGY311Y1", "PSL350H1"]}]}'::jsonb),
    ('HMB442H1', 'Brain Tumours: From Diagnosis to Treatment Effects', '16L/8S', 'This course focuses on current insights in brain tumour etiology and pathology as well as treatment options and side-effects. Based on a seminar format, this course is highly discussion-based and collaborative in nature.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", {"operator": "OR", "items": ["HMB302H1", "HMB322H1", "HMB300H1", "HMB360H1", "CJH332H1"]}]}'::jsonb),
    ('HMB443H1', 'Global Hidden Hunger', '18L/6S', 'Vitamin and mineral deficiencies, termed ''hidden hunger,'' affect about half the world''s population. Explore the global nature, catastrophic consequences, and causes of these deficiencies. Discuss formulation and implementation of international, national, and local policies to alleviate ''hidden hunger'' especially in infants and young children. A service-learning opportunity is integrated. Students will be required to contribute to a local community organization while using course knowledge to develop a project or initiative beneficial to the organization and community. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. The application will ask about motivation and/or relevant experience. Applications are received during priority course enrollment, and late applications considered if space remains. Specific application review and response dates will be available on the HMB Special Enrolment website. Applications will be assessed based on prerequisites, submitted answers to application prompts and cGPA. This course is open to all Human Biology students.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": [{"credits": 0.5, "department": null}, "NFS382H1"]}]}'::jsonb),
    ('HMB450H1', 'Neurodevelopmental Diversity and Diseases', '24L/12T', 'Brain development plays a critical role in human health as early neurological mechanisms provide the foundation for future complex neurological processes. This course will examine how neurodevelopmental differences contribute to neurological diversity, disorders and/or diseases, such as autism, epilepsy, and paediatric multiple sclerosis. Current research from basic, translational, and clinical perspectives will be examined. Case studies, the impact of neurodevelopmental differences, and respect for neurodiversity will be emphasized.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB200H1", {"operator": "OR", "items": ["HMB320H1", "ANA300Y1", "JHA410H1"]}]}'::jsonb),
    ('HMB452H1', 'Personalized Medicine', '12L/12S', 'The bridge between basic scientific research and clinical practice integrates fundamental knowledge about molecular/cellular mechanisms and clinical disorders to increase the potential for new medical treatments and technologies as well as understanding of disease processes. Specific topics vary from year to year and will be based on the course instructor''s area(s) of expertise.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB302H1", "HMB321H1", "HMB322H1"]}]}'::jsonb),
    ('HMB453H1', 'AIDS: A Global Perspective', '6L/18S', 'Seminars explore the global AIDS crisis. Varying epidemiological profiles of AIDS are placed in broader biological, social, and cultural frameworks. The impact of globalization and structural inequality on local cultures and lifestyles provides a backdrop to the discussions.', 'HAJ453H1', 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": [{"credits": 0.5, "department": null}, "JSU237H1", "PHS300H1", "JNH350H1"]}]}'::jsonb),
    ('HMB460H1', 'Seminars in Neurobiology of Mental Health', '12L/12S', 'This seminar course focuses on recent research into the neurobiology underlying mental health issues and is highly discussion-based and collaborative in nature. Specific topics are indicated by subtopic (which may vary yearly).', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB200H1", "HMB300H1", {"operator": "OR", "items": ["HMB320H1", "ANA300Y1", "JHA410H1"]}]}'::jsonb),
    ('HMB462H1', 'Topics in Epidemiology', '12L/12S', 'The focus is on the theory and application of biostatistics and epidemiology to current developments in special topics in substantive areas of epidemiology (e.g., chronic disease, environmental & occupational health, infectious disease, methods, social, etc.).', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "HMB342H1"]}'::jsonb),
    ('HMB470H1', 'Exercise and Sports Medicine', '22L/4S', 'This course considers the health benefits and risks of different forms of exercise, with a goal of understanding how people should exercise, and how much, depending on their athletic and health goals. It introduces elements of exercise science including the biomechanics of tissues and injuries to develop an understanding of how both the quantity and quality of movement and loading contribute to healthy training and/or injury. Some common injuries in sport such as knee injuries and concussions are used as examples of how various patterns of loading can cause injuries.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", "PSL301H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('HMB471H1', 'Performance Enhancement', '24L/4P', 'Enhancing performance has broad appeal. This course explores current developments for achieving peak performance academically, physically and emotionally. We focus on the scientific basis of the links between performance and stress, and of the benefits and risks of pharmacological methods to achieve performance enhancement. Various stress management skills are introduced.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('HMB472H1', 'Exercise Physiology', '20L/4S', 'Examine the physiological and biochemical responses of the human body to both acute and chronic bouts of physical activity. The impact of activity on health, and health on physical activity, is explored by examining adaptations from the cellular to the systemic level of bodily function.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", "PSL301H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('HMB473H1', 'Exercise and Mental Health', '18L/10P/6S', 'This course, featuring a service-learning component, discusses how mental well-being is a critical element of total health. We explore the evidence underpinning the role of physical activity in the avoidance of mental disorders, recovery from mental disorders, and the quality of life of those with or without mental disorders. A short application to enrol in this course is required. Information may be found via the Human Biology Program website.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", "PSL301H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('HMB474H1', 'Dental Sciences', '20L/4S', 'Dentistry is one of the oldest branches of medicine responsible for the treatment of diseases of oral cavity. This course will introduce students to the key concepts as well as the latest research in the dental sciences, including but not limited to craniofacial structures, bone physiology, odontogenesis, pathogenesis of oral diseases, and technology in dental sciences.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PSL300H1", "PSL301H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('HMB489H1', 'Advanced Laboratory in Human Biology', '36P/12S', 'Building on their experience in 3rd-year labs, students participate in inquiry-based laboratory experiments in diverse areas of current human biology research. Open to students in any Human Biology program. Labs start in the first week of term. (Lab Materials Fee: $132)', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HMB310H1", "HMB311H1", "HMB312H1", "HMB314H1"]}]}'::jsonb),
    ('HMB490Y1', 'Health in Community', '24L/24T', 'An experiential learning course exploring health-related challenges and social determinants of health in partnership with local community organizations. Lectures and tutorials will support learning of selected biological and social aspects of health and disease, neuroscience, genetics or population health, and the development of scientific knowledge translation skills relevant to the community agencies. Cannot be taken concurrently with a full year research project course. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. The application will ask about motivation and/or relevant experience. . Applications are received during priority course enrollment, and late applications considered if space remains. Specific application review and response dates will be available on the HMB Special Enrolment website. Applications will be assessed based on prerequisites, submitted answers to application prompts and cGPA. This course is open to all Human Biology students.', 'HMB473H1', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, "BCH210H1", "PSL300H1", "PSL301H1", {"operator": "OR", "items": ["HMB200H1", "HMB201H1", "HMB202H1", "HMB203H1", "HMB204H1"]}]}'::jsonb),
    ('HMB491Y1', 'Project in Biotechnology Industry', '12L/200P/12S', 'Students undertake an academic internship in the biotechnology sector, in addition to meeting regularly in class to discuss and share their experiences. The course is designed to provide students with an opportunity to apply academic learning in a professional context, build their network, and explore potential career paths. Students will be required to complete 200 hours with a placement partner over the duration of the course (normally 8 hours/week). The course is open to fourth year students. Students work with course staff to secure their internship with our partner organizations. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. Application packages will be accepted in April every year, and specific due date, course/placement information, and the application form can be found in the website. The application will ask about goals, course expectations and relevant knowledge & experience. Applications will be assessed based on prerequisites, submitted answers to application prompts and relevant knowledge. Course enrolment will be based on the number of internship opportunities available (which will vary from year-to-year), student qualifications (e.g. performance in relevant courses, qualifications related to the internship positions on offer, and interview performance). Final acceptance into the course is dependent on the official acceptance of a student as an intern with a partner organization. Not eligible for CR/NCR option.', 'ASIP Program,  HMB490Y1, not recommended to take with another full year project course. Anyone considering taking two projects needs course instructors approval first.', 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["STA288H1", "STA220H1", "PSY201H1", "EEB225H1"]}]}'::jsonb),
    ('HMB496Y1', 'Research Project in Human Biology', null, 'A research project course for students enrolled in a Human Biology program, supervised by a faculty member appointed in a faculty or division at St. George Campus (Faculties of Arts & Science, Medicine, Engineering, Dalla Lana School of Public Health, etc.). Open to third and fourth year students. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. For your application to be submitted and considered, you must first secure a supervisor for your research project. Applications are due by May 1 for the summer term or September 1 for the fall/winter terms, though students are encouraged to start looking for a supervisor at least 6 months in advance. This course is open to all Human Biology students. Should a HMB Specialist require help securing a supervisor, the request must be made by email to the Human Biology Program Office no later than July 20 for Academic year projects and January 30 for Summer projects. Not eligible for CR/NCR option.', 'Students are not permitted to do a HMB research project concurrently with another research project', null, null::jsonb),
    ('HMB499Y1', 'Research Project in Human Biology II', null, 'A research project course for students enrolled in a Human Biology program, supervised by a faculty member appointed in a faculty or division at St. George Campus (Faculties of Arts & Science, Medicine, Engineering, Dalla Lana School of Public Health, etc.). Open to third and fourth year students. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. For your application to be submitted and considered, you must first secure a supervisor for your research project. Applications are due by May 1 for the summer term or September 1 for the fall/winter terms, though students are encouraged to start looking for a supervisor at least 6 months in advance. This course is open to all Human Biology students. Should a HMB Specialist require help securing a supervisor, the request must be made by email to the Human Biology Program Office no later than July 20 for Academic year projects and January 30 for Summer projects. Not eligible for CR/NCR option.', 'Students are not permitted to do a HMB research project concurrently with another research project.', null, '{"operator": "AND", "items": ["HMB496Y1"]}'::jsonb),
    ('HMU111H1', 'Introduction to Music and Society', null, 'An examination of musical thought and practice in non-Western and Western traditions.', 'Does not count as an HMU elective.', null, null::jsonb),
    ('HMU126H1', 'Historical Survey II', null, 'Western music from 1750 to the present.', 'HMU226H1. Does not count as an HMU elective.', null, null::jsonb),
    ('HMU225H1', 'Historical Survey I', null, 'Western music up to 1750.', 'Does not count as an HMU elective.', null, null::jsonb),
    ('HMU345H1', 'Global Popular Musics', null, 'Global Popular Musics is an introduction to popular music in its social and cultural context in a variety of international settings. Genres to be covered may include, but are not limited to, rock, hip-hop, country, and “world music”. The course will take an issues-based approach to the study of popular music, focusing on topics such as the interplay of tradition and modernity; media and technology; race, gender, sexuality, class, and other facets of identity; urbanization and migration; and the markets and legal structures surrounding music.', 'HMU245H1', null, '{"operator": "AND", "items": ["HMU111H1", "HMU126H1", {"operator": "OR", "items": ["HMU225H1", "JMU210H1"]}]}'::jsonb),
    ('HMU425H1', 'Topics: Medieval Music', null, 'Plainchant and polyphony, including topics for individual research.', 'HMU330H1', null, null::jsonb),
    ('HMU431H1', 'Topics: Romantic Music', null, 'Instrumental and vocal genres, including topics for individual research.', null, null, null::jsonb),
    ('HMU432H1', 'Topics: 20th Century Music', null, 'Developments and trends since 1910, including topics for individual research.', null, null, null::jsonb),
    ('HMU433H1', 'Topics: Ethnomusicology', null, 'The history of the discipline from its roots in Comparative Musicology in the 1880s to the modern, holistic study of music and society. Other topics include transcription, transmission, and cultural appropriation. A variety of the world''s traditions are illustrated with audio-visual materials, and students contribute personal surveys, analyses and debates.', null, null, null::jsonb),
    ('HPS100H1', 'Introduction to History and Philosophy of Science and Technology', '24L/10T', 'An investigation of some pivotal periods in the history of science with an emphasis on the influences of philosophy on the scientists of the period, and the philosophical and social implications of the scientific knowledge, theory and methodology that emerged.', null, 2, null::jsonb),
    ('HPS110H1', 'The Science of Human Nature', '24L/10T', 'Why do we do what we do? What factors play a role in shaping our personality? What biological and social elements help configure a person''s moral and emotional character? In this course, we examine landmark studies that shook standard beliefs about human nature in their time. We analyze those studies in their historical context and discuss their relevance to social, ethical, and policy debates. The studies may include research on obedience, conformity, prejudice, aggression, attachment, empathy, altruism, race and gender stereotypes, happiness, resilience.', null, 2, null::jsonb),
    ('HPS120H1', 'How to Think about Science', '24L/10T', 'This course addresses the nature of science and its importance to our understanding of ourselves. Questions include: What is a science? Is science objective? What is scientific reasoning? Has our conception of science changed through history? How does science shape our moral image? Does science reveal our natures as humans?', null, 2, null::jsonb),
    ('HPS200H1', 'Science and Values', '24L', 'An introduction to issues at the interface of science and society. Including the reciprocal influence of science and social norms, the relation of science and religion, dissemination of scientific knowledge, science and policy. Issues may include: Nuclear, Biological and Chemical Weapons; Genetic Engineering; The Human Genome Project; Climate Change.', null, 3, null::jsonb),
    ('HPS201H1', 'Science, Technology, and Society: Methods and Approaches', '24L/12T', 'This course introduces students to the methods and concepts of STS, an interdisciplinary approach to studying science and technology in society. Students will gain familiarity with some of the major theoretical tools used by STS scholars, including but not limited to: actor-network theory (ANT); the sociology of scientific knowledge (SSK); technopolitics and the social construction of technology (SCOT); feminist and postcolonial approaches to the study of science, technology and society; and more. STS methods will be paired with a variety of case studies related to past and present controversies, institutions, artifacts, policies, and cultures.', 'VIC172Y1', 3, null::jsonb),
    ('HPS202H1', 'Technology in the Modern World', '24L/10T', 'This course examines the reciprocal relationship between technology and society since 1800 from the perspectives of race, class, and gender. From the role of European imperial expansion in 19th-century industrialization and mechanization to the development of nuclear technology, smartphones, and digital computers in the 20th century, we consider cultural responses to new technologies, and the ways in which technology operates as an historical force in the history of the modern world.', null, 3, null::jsonb),
    ('HPS203H1', 'Making Sense of Uncertainty', '24L/12T', 'This course examines issues of uncertainty in various contexts of science, technology, and society since the 19th century. Topics may include randomized controlled trials, statistical identification of normal and pathological, biopolitics, philosophical interpretations of probability, Brownian motions, uncertainty principle in quantum mechanics, cybernetic mind, and chance in avant-garde arts.', null, 2, null::jsonb),
    ('HPS205H1', 'Science, Technology, and Empire', '24L/6T', 'This gateway course introduces the emergence of modern science and technology and the rise of European mercantile and colonial empires as closely intertwined processes. Beginning with the European discovery of the Americas, this course provides a broad thematic overview of the transformation of scientific practices in imperial contexts, including but not limited to geography and cartography; medical botany and plantation agriculture; biogeography and evolutionary biology; ecology and environmentalism; and race science and anthropology. The course primarily focuses on British and French colonial contexts in South Asia, Africa, Australasia and the Americas, but also considers Iberian, Russian, Dutch, and other imperial formations.', null, 3, null::jsonb),
    ('HPS208H1', 'How We Think About Life', '24L/12T', 'What is the difference between living and non-living things? How should living things be classified? How do various kinds of life relate to each other and to the non-living environment? These are perennial questions, dealt with by every culture throughout history, and still debated today. This course surveys historical and cultural contexts of efforts to understand life, taxonomy, and ecology, and modern questions in the philosophy of the life sciences. The historical and cultural approach will help us to understand changing views, similarities, and differences among various understandings of life. And our approach to philosophy will be critical, asking what the best arguments for various current views are. Topics covered may include ecology, evolution, heredity, natural history, taxonomy, and definitions of life.', null, 4, null::jsonb),
    ('HPS212H1', 'Global Digital: Information, Computing, and Communication in the Modern World', '24L/6T', 'From integrated circuits and the internet to social media and machine learning, digital technologies are a crucial part of modern life. How have they been developed in the contexts of the Cold War, neoliberal economic order, mass media, and crowdsourcing? In what ways have they shaped sociability, governance, production, and reasoning? How have they intertwined with the changing scientific understandings of the worlds? In this course, we examine select digital technologies and their co-production with society. We emphasize their global aspects: international tech ecosystems, transnational research and development, and political or cultural transformations facilitated by digital devices or systems.', 'HPS301H1 (offered as "Global Digital: Information, Computing, and Communication in the Modern World") taken in Winter 2023', 3, null::jsonb),
    ('HPS220H1', 'Machines', '24L/11T', 'Machines pervade our lives and their influences are woven through countless contemporary debates in both academic and public discourse. The term ''machine'' is used frequently in ordinary language, in literature, as well as in philosophical and scientific discussions, yet the concept itself—it''s history, meaning, and impact—rarely gets the analysis it deserves. This course explores the meanings and influence of machines for knowledge, culture, and society in different periods and places, both real and imaginary, through the lens of the history and philosophy of technology. We will draw on scholarship and expertise from a range of fields, including history, philosophy, anthropology, human-machine interaction, computer science, sociology, and literary studies, to explore what machines have been, what they have become, and what they mean for our societies.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS222H1', 'Science, Paradoxes, and Knowledge', '24L/10T', 'What is the nature of science and scientific knowledge? What is the nature of space, time and motion? Does science tell us the truth about the world? What are scientific revolutions and how they occur? The course will address these and various other questions about science. It will focus on the bearings that philosophical views had on science in different periods in history, starting from ancient Greece and concluding in the 20th C.', null, 2, null::jsonb),
    ('HPS225H1', 'Remaking the Past: The Re-creation and Re-enactment of Science and Technology', '24L/12T', 'One path to understanding the knowledge of the past is by attempting to re-create it. From rebuilding and sailing ancient sea vessels to reenacting scientific experiments, re-creation is used to investigate past approaches to technology and science. Using such methods, researchers seek to understand what was known, and also to experience how it was known. But, a persistent question remains: are authentic experiences truly possible across distances of time and culture? The course surveys several academic domains to explore how an array of approaches to re-creation are used and understood. As a term assignment, participants will design and share their own hypothetical re-creation project.', null, 2, null::jsonb),
    ('HPS240H1', 'The Influence of the Eugenics Movement on Contemporary Society', '24L/10T', 'This course explores present-day topics such as reproductive issues (including “designer babies” and genetic counselling), gender, racism/colonialism, disability and euthanasia through the lens of the history of eugenics. A “scientific” movement which became popular around the world in the early twentieth century, eugenics was based on the principle that certain undesirable human characteristics were hereditary and could be eliminated by controlled reproduction. It resulted in the enactment of laws in numerous places, including Canada, authorizing coerced reproductive sterilization of certain individuals, and other measures intended to “improve” humanity. Today, we see its influences woven through contemporary debates, a number of which we will consider.', null, 3, null::jsonb),
    ('HPS245H1', 'Visions of Society and Progress', '24L/12T', 'This course explores influential visions of society and progress found in the history of the human sciences. It addresses questions such as: Are human beings naturally selfish or cooperative? Is society in harmony with the individual or opposed to the individual? It explores the significance of race, class, population growth, capitalism, and gender in debates about the good society.', 'HPS352H1', 2, null::jsonb),
    ('HPS246H1', 'Data and Society: What''s Behind the Numbers?', '24L/12T', '"Big data" and "data-driven" approaches have become central to our modern scientific, cultural, and political landscapes. Yet rarely do we stop to think about what these notions mean or how they relate to ways of living in and knowing the world around us. Students in this course will consider what it means to produce data, who/what gets in/excluded, and how a critical examination of the data-making process can inform a more socially just and equitable future.', null, 2, null::jsonb),
    ('HPS250H1', 'Introductory Philosophy of Science', '24L/10T', 'This course introduces and explores central issues in the philosophy of science, including scientific inference, method, and explanation. Topics may include underdetermination, realism, empiricism, scientific revolutions, feminist epistemology, and laws of nature.', null, 2, null::jsonb),
    ('HPS255H1', 'History and Philosophy of Artificial Intelligence', '24L/12T', 'This course introduces students to the historical and philosophical issues around artificial intelligence (AI). We will cover the geopolitical, economic, and cultural contexts from which the field of AI emerged, as well as the troubled history of the scientific concept of intelligence and how that has influenced the development of AI. The course will also introduce students to foundational and normative questions, such as how we should define and measure AI, how to evaluate the accomplishments of AI systems, and what the benefits and risks of relying on such systems might be.', null, 3, null::jsonb),
    ('HPS260H1', 'Biology and the Future: Science and Science Fiction', '24L/6T', 'This lecture course explores the fantastic visions of humanity''s future inspired by the advance of the biological sciences during the twentieth century. Biology provided the scientific underpinning for societal hopes and fears embodied in such cultural icons as robots, aliens, "brains in a vat," and super-humans.', 'HMB444H1', 1, null::jsonb),
    ('HPS270H1', 'Science and Literature', '24L/10T', 'This course will focus on the interplay between science and literature from ancient Greece to the present day. We''ll examine the impact of major scientific paradigm shifts on the literature of their time, and situate literary texts within the context of contemporary scientific discoveries and technological innovations.', null, 2, null::jsonb),
    ('HPS272H1', 'Science against Religion? A Complex History', '24L', 'This course introduces students to the central topics arising from the encounter between modern science and religion. It aims to integrate historical and philosophical perspectives about science and religion. Did modern science arise because of Christianity or despite of it? Are science and religion necessarily in conflict? Have they factually always been in conflict throughout history? Are proofs of God''s existence obsolete? Has science secularized society? What role should religions play in liberal democracies?', 'HPS326H1', 3, null::jsonb),
    ('HPS299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HPS299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HPS300H1', 'Topics in History and Philosophy of Science and Technology', '24L/10T', 'Topics vary year to year.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS301H1', 'Topics in the History of Science and Technology', '24L/10T', 'This course can concern topics of special interest in the history of science from Antiquity until present. Topics may focus on specific-time periods, fields of inquiry, individuals, scientific institutions, or geographic locations. Content in any given year depends on instructor. Refer to the Institute for the History & Philosophy of Science & Technology website for more information.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS302H1', 'Topics in Philosophy of Science and Technology', '24L/10T', 'This course can concern topics of special interest in the philosophy of science from Antiquity until present. Topics may include scientific change, rationality, method, evidence, progress, reduction, scientific laws, models, representation etc. The course may also focus on specific-time periods, fields of inquiry, individuals, scientific institutions, geographic locations, etc.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('HPS304H1', 'A History Lab: Biomedical Sciences, Past and Present', '36S', 'Offers a hands-on introduction to historical research. Through a close examination of classic scholarly texts, archival materials, and recent media publications, this advanced seminar explores the sources, methods, and approaches in historical studies of biomedical twentieth century-sciences.', null, 1, null::jsonb),
    ('HPS316H1', 'Environment, Technology, and Nature', '24L/10T', 'This course examines the intersection of technology and environment in the modern world. Whether simple or complex, whether designed for recreation, work, or warfare, our tools and how we use them filter our perceptions of, and engagements with, non-human nature.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"credits": 0.5, "department": "HPS"}, {"credits": 0.5, "department": "HIS"}]}]}'::jsonb),
    ('HPS318H1', 'History of Medicine I', '24L/10T', 'This course explores how medicine was practiced, taught and theorized from ancient Greece to the early modern period. It focuses on the historical development of western medicine in relation to societies, politics and culture, and considers topics such as the creation of medical traditions, the transmission and communication of medical knowledge, the pluralistic world of healers, the role of religion, magic and natural philosophy, the cultural meaning of disease, and the emergence of institutions such as the hospital.', 'HPS314Y1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS319H1', 'History of Medicine II', '24L/10T', 'This course examines the development of medicine from the seventeenth to the twentieth century. It focuses on the historical development of western medicine in relation to societies, politics and culture and considers topics such as changing views of the body, the development of medical institutions such as hospitals, asylums and laboratories, the diversifies world of healing and the place of visual and material culture in the production and dissemination of medical knowledge.', 'HPS314Y1,  HPS315H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS321H1', 'Understanding Engineering Practice: From Design to Entrepreneurship', '6T/24S', 'This course seeks to understand the nature of engineering practice, which comprises complex social, intellectual, and technical actions at various stages from design to entrepreneurship. Building upon the history and social studies of technology, philosophy of engineering, business history, and management science, we introduce ways to analyze such complex actions.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('HPS322H1', 'Complexity, Order, and Emergence', '10T/24S', 'A survey of the history of and recent developments in the scientific study of complex systems and emergent order. There will be particular emphasis on the biological and cognitive sciences. Topics covered may include: mechanism and teleology in the history of science, 19th and 20th century emergentism, complex systems dynamics, order and adaptiveness, self-organization in biology and cognitive development.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": [{"credits": 0.5, "department": "HPS"}, {"credits": 0.5, "department": "PHL"}]}]}'::jsonb),
    ('HPS324H1', 'Natural Science and Social Issues', '24L', 'Historical examination of the interactions of science (both as body of knowledge and as enterprise) with ideological, political and social issues. The impact of science; attacks on and critiques of scientific expertise as background to contemporary conflicts. Subjects may vary according to students interests. (offered irregularly)', null, 3, null::jsonb),
    ('HPS325H1', 'Modern Science and Holy Texts', '24L', 'This course explores interdisciplinary topics related to the encounter between modern science and texts accepted as holy by religious communities, such as the Bible in Christianity. What role did holy texts play in the emergence of modern science? Did modern science change the way religious communities interpret their holy texts? What to do with claims such as that the Quran contains quantum physics? Does modern science exhibit the same kind of rationality that we find in rabbinical Judaism? Do holy texts only exist to assist humanity''s attempts at understanding the meaning of the world, while modern science actually explains the world? What role do texts play in modern science compared to holy texts in religious communities? And, what has modern science to say about the very idea of holy texts?', null, 3, null::jsonb),
    ('HPS331H1', 'How Maps Transform the World, Society, and Ourselves', '24L/12T', 'Maps are pervasive in our world: so indispensable, and so disposable that thousands are made, used, and discarded every day. Yet not long ago, maps were both rare and strange technological things. When and why did modern mapping systems come into being? Behind this transformation lie contentious stories of objects and people, makers and users, global forces and local dynamics, metropoles and colonies, and technologies and cultures. Focusing on the modern period, each week illuminates maps and their importance in our world by focusing on a keyword, such as power, territory, worldmaking, boundaries, imperialism, capitalism, literacy, verticality, and countermapping.', 'HPS301H1 (Topics in the History of Science: A Global History of Mapping Sciences), offered in Winter 2022', 3, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"credits": 0.5, "department": "HPS"}, {"credits": 0.5, "department": "HIS"}]}]}'::jsonb),
    ('HPS340H1', 'The Limits of Machine Intelligence', '24L/11T', 'With the recent headline-making breakthroughs in deep learning neural networks (DNNs), it might seem that we are on the cusp of living with artificial systems that match or exceed human intelligence. But there remain longstanding philosophical challenges around the definition of intelligence that AI researchers use, how they measure the performance of their systems, and what DNNS could really be capable of, that still need addressing. For example, how close are DNNs to passing the Turing test? How close are we to building general intelligence and what do we need to get us there? How can we draw fair and meaningful comparisons between artificial and biological systems? We will draw on material from the history and philosophy of science to evaluate and inform current debates around the limits of AI. For example, we''ll consider what kinds of explanations DNNs can provide. We''ll also look at how debates between the rationalists and empiricists (e.g. Locke, Hume, and Kant) inform current debates between AI nativists and empiricists. This course explores these questions through contemporary texts across the fields of philosophy of science, artificial intelligence, comparative psychology, and cognitive science, among others.', 'HPS300H1 (Topics in History and Philosophy of Science and Technology: The Limits of Machine Intelligence), offered in Winter 2021 and Fall 2021', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": [{"credits": 0.5, "department": "HPS"}, {"credits": 0.5, "department": "PHL"}, {"credits": 0.5, "department": "COG"}]}]}'::jsonb),
    ('HPS345H1', 'Quantifying the World: Debates on the Ethical and Epistemic Implications of AI and Automation', '24L/12T', 'The effects of automation, computing, and information technology have had a great impact on our society. The rise of automation and computing the almost cult-like trust in mechanization have transformed our society both at the material and the epistemological level. This course will examine the epistemological and ethical debates that AI and automation have produced in all sectors of society. It will consider a variety of media and instruments from data visualization and mapping, to the use of AI and robotics, contextualizing them within popular and hotly contested examples in the military field and in cybersecurity, in medical diagnostics and epidemiology, in the automotive industry, and in the personal realm.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS346H1', 'Modifying and Optimizing Life: on the Peculiar Alliance between AI, Biology, and Engineering', '24L/12T', 'Taking cue from the entanglements that historically have pervaded the relation between biology and information technology since the early 20th century, this course interrogates the sociocultural and technological conjuncture that has brought computer science, biology and engineering together into peculiar, ingenious, and often controversial alliances. What do AI, synthetic biology, and biotechnology have in common? How have they come to be associated? What are the debates and ethics emerging from such associations? The course will focus on topics such as: geoengineering and bioremediation; GMO and Robotic insects; the use of expert systems and machine learning to optimize synthetic biology; the flourishing and marketing of precision and personalized medicine/immunotherapy; and the ethics behind CRISPR babies.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HPS347H1', 'History of Autism Across Time and Cultures', '24L/12T', 'What is autism? When was it first identified as a condition? How has its meaning changed over time? How does the autistic experience vary across cultures? This course covers the history of autism, the social understandings and cultural meanings of autism, and the autistic experience through time and across cultures. It introduces students to both historical and contemporary perspectives, including scientific accounts, cultural representations, and the voices of autistic people. Through the case of autism we will grapple with larger issues such as the role of medical and social views in shaping definitions of mental normality and pathology, the changing meaning of disability in different cultures, and the experience of living with a developmental disability.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS351H1', 'Biomedical Sciences and Technologies in Global Society', '24L/12T', 'This course examines how the contemporary life sciences intersect with global geopolitics through an introduction to the field of science and technology studies (STS). Using interdisciplinary methodologies and global perspectives, the course addresses key questions including: Who benefits from the development of new biotechnologies, and who is exploited in the process? Who sets the international norms of bioethics and medical market regulation? How are biologists and medical practitioners redefining life for different societies and their diverse constituencies? The course predominantly focuses on humans, but also introduces new scholarship on animal studies and synthetic life forms. It has significant coverage of the Middle East, Africa, and East and South Asia.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('HPS354H1', 'History of Medicine and Public Health in the Middle East', '24L/6T', 'This course provides a broad thematic overview of the history of medicine and public health in the Middle East. Focusing on the modern period, the course highlights the region as a contact zone of medical traditions and a key site in the emergence of colonial medicine and international public health. Students examine the social and cultural effects of new developments in medical thought and practice, including ideas about contagion and disease prevention, the notion of public health and hygiene, and the construction of colonial and postcolonial medical schools and hospitals.', null, 3, null::jsonb),
    ('HPS370H1', 'Philosophy of Medicine', '24L/12T', 'This course introduces students to philosophical issues in the study of medicine. The course will cover foundational questions, such as what constitutes evidence that a therapy is effective, how do we define health and disease, and information derived from research is used to support clinical practice. Students will be introduced to different movements in contemporary clinical medicine, such as Evidence-based Medicine, Person-Centered Healthcare, and Precision Medicine.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('HPS371H1', 'COVID-19: Epistemology and Societal Implications', '24L/12T', 'The COVID-19 pandemic led to significant changes in our daily lives, society, medicine, and public health. This course will examine the pandemic and the public response through a philosophy of science lens. In particular, students will explore philosophical issues about how the healthcare community generates knowledge and how that knowledge is used to inform responses to a major public health crisis. The course will also provide a brief history of pandemics and examine Coronavirus in a historical context. Epistemological issues regarding pandemic modelling and epidemiology, clinical research and generalizability of findings, diagnostic testing, public health response (e.g. border closures, protective masks, social distancing, isolation, testing and tracking), and economic and social impact will be covered. Portrayals of the pandemic by media, government, and scientists will also be examined. Readings will be drawn from a variety of academic disciplines and popular sources.', null, 2, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('HPS372H1', 'The Epistemology of Medical Misinformation', '24L/12T', 'The epistemology of misinformation is a branch of epistemology with the objective of providing insight into the nature and spread of misinformation, fake news, conspiratorial theories, echo chambers, and epistemic pathologies in the formation of public opinion. This course focuses on medical misinformation, what harms it can cause, how it spreads, and strategies that have been advanced to minimize the harm of medical misinformation. Through a series of case studies, it also provides a critical perspective on the difference between misinformation and disinformation with an overview of how threat actors weaponize information during public health emergencies to cause harm. Topics covered may include concepts of scientific objectivity and universality; the communication of risk and risk perception; and the changing role of expertise in a fragmented public sphere; and the key role played by mainstream and social media in spreading both information and disinformation, propaganda, conspiracy theories, and fake news.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": ["HPS100H1", "HPS200H1", "HPS120H1", "HPS250H1", "VIC173H1", "PHL250H1", "PHL255H1"]}]}'::jsonb),
    ('HPS390H1', 'The Story of Number: Mathematics from the Babylonians to the Scientific Revolution', '24L/12T', 'A survey of ancient, medieval, and early modern mathematics with emphasis on historical issues.', 'HPS310Y1;  MAT220Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HPS391H1', 'Rebels Who Count: The History of Mathematics from 1700 to the Present', '24L/12T', 'A survey of the development of mathematics from 1700 to the present with emphasis on historical issues.', 'HPS310Y1;  MAT220Y1,  MAT391H1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HPS399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HPS399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HPS401H1', 'Scientific Artifacts', '24S', 'This course explores the history of science through direct engagement with local scientific artifacts within the University of Toronto Scientific Instrument Collection (UTSIC.org). Each student will undertake a research project focused on a single artifact within the collection in order to explore both the local history of science and the methodology of material culture research as it relates to science.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS402H1', 'Animals in the Histories of Science and Technology', '24S', 'What can a focus on nonhuman animals reveal about the knowledge practices and politics of science and technology? This course approaches the history of science from the perspective of nonhuman animals in order to revisit—and retell—the history of various scientific disciplines and practices. We will consider how the various ways in which animals have been enrolled into the formation of scientific knowledge, from laboratory settings to ecological fieldwork, to colonial natural history. Students will learn to interrogate anthropocentric biases in the histories of science and technology, and to assess the significance of nonhuman animals in the formation of scientific knowledge.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS403H1', 'Vegetarianism and Veganism:  Science, Technology, Human Health, Animal Welfare, and the Environment', '24S', 'This is an advanced undergraduate seminar that examines the past, present, and future of vegetarianism and veganism, with a focus on five central themes: science, technology, human health, animal welfare, and the environment. Along the way, we will consider many other important issues and contexts as well, such as: factory farming, capitalism, social identities and inequalities associated with gender, race, and class, religious beliefs and practices, high-performance sports, and cultural resources such as documentary films, television programs and music videos. Students will engage in discussions, make class presentations, and carry out original research projects.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.5, "department": "HPS"}]}'::jsonb),
    ('HPS410H1', 'History of Mathematics', '24S', 'Historical examination of mathematics, focusing on certain themes and time periods, to show how mathematics has changed and evolved.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HPS411H1', 'Conceptual Foundations of Mathematics', '24S', 'An examination of foundational and conceptual aspects of mathematics such as: the nature of mathematical objects, logicism, Church''s elementalistic mathematics, Gödel''s theorem and formal systems, postulational methods, mathematics and reality, the cardinal, ordinal and abstract approaches to numbers, infinity, and Euclidean and non-Euclidean geometries.', null, 5, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HPS412H1', 'History of the Biological Sciences', '24S', 'Historical examination of the biological sciences, focusing on certain themes and time periods.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS413H1', 'Reading and Writing about Physics', '24S', 'Historians, philosophers, and sociologists have produced a wealth of literature on the analysis and examination of physics from the early modern period to the present. In this seminar, we read and discuss in depth a collection of recent classics and cutting-edge works on the historical studies of physics. Students also conduct research based on this literature. We aim to use physics as a lens to understanding key themes in the making of modern science, from incommensurability, epistemic cultures, and historical ontology, to materiality, social construction, pedagogy, and countercultures.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS422H1', 'History of Data', '24S', 'This seminar examines the meaning and value of data in a variety of historical contexts. Important moments in the history of science will be considered through scholars'' attempts to catalog and quantify human lives, social dynamics, and natural phenomena. Course material will focus on the relationship between the production of data and different forms of knowledge, power, and governance.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HPS430H1', 'History of Technology', '24S', 'This course offers a focused discussion of various topics and themes within the history of technology. Content in any given year varies by instructor. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HPS440H1', 'Topics in History of Medicine', '24S', 'This course offers a focused discussion of several aspects of the history of medicine. Various themes are examined in depth year to year so as to familiarize students with different topics and methodological approaches.', 'HPS303H1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HPS318H1", "HPS319H1", {"credits": 1.0, "department": "HPS"}]}]}'::jsonb),
    ('HPS442H1', 'Sciences of Whiteness in the Middle East & Its Diasporas', '24S', 'This research seminar traces the historical response of Middle Eastern societies and diasporas to Western scientific discourses of race and ethnicity from the 19th century to the present. We examine notions of racial classification and hierarchy as they emerged in Islamicate and European imperial contexts and their scientific application to Middle Eastern populations. We further investigate how the nationalist ideologies of modern Middle Eastern nation-states relied on and perpetuated race science. Finally, we consider the experience of Middle Eastern migrants to Europe and North America and their engagement with scientific definitions of Aryan, Caucasian and white racial identity.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('HPS444H1', 'Health, Medicine, and Society in the Mediterranean World', '24S', 'This course examines healing practices and medical knowledge in the Mediterranean world, focusing on the early modern period. We will address topics such as the interplay between medicine and religion, the relationship between patients and practitioners, and the role of women as both healers and patients and across Mediterranean shores. We will also consider how individuals in different Mediterranean regions experienced the relationship between health and the environment, explore the bearings that medical pursuits had on the creation and consolidation of notions of sex and gender, and examine how medical knowledge shaped views of the body and informed health policies.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["HPS205H1", "HPS240H1", "HPS245H1", "HPS260H1", "HPS301H1", "HPS304H1", "HPS316H1", "HPS318H1", "HPS319H1", "HPS331H1", "HPS351H1", "HPS354H1", "HPS402H1", "HPS412H1", "HPS430H1", "HPS431H1", "HPS442H1", "HIS218H1", "HIS313H1"]}]}'::jsonb),
    ('HPS445H1', 'Slavery, Medicine, and Science', '24S', 'This course will study historical entanglements of slavery, science, and medicine. On the one hand, it will examine 1) the different ways in which medicine and science supported the institution of slavery; and 2)the sites in which slavery was integral to processes of production, movement and transfer of medical and scientific knowledge and practices. On the other hand, it will consider the voices of enslaved individuals, and accordingly cast light on the epistemic role of enslaved communities in the histories of science, medicine, and technology.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["HPS318H1", "HPS319H1", "HPS202H1", "HPS205H1", "HPS240H1", "HPS245H1", "HPS260H1", "HPS301H1", "HPS304H1", "HPS316H1", "HPS331H1", "HPS351H1", "HPS354H1", "HPS379H1", "HPS402H1", "HPS412H1", "HPS430H1", "HPS431H1", "HPS442H1", "HIS218H1", "HIS313H1", "NMC379H1", "HIS305H1", "HIS390H1", "HIS446H1", "HIS453H1"]}]}'::jsonb),
    ('HPS450H1', 'Revolutions in Science', '24S', 'A detailed investigation into a highly celebrated and important philosophical idea concerning the development of scientific knowledge: the notion of scientific revolutions. We will consider the process of theory change, whether theory choice is rational, and whether theoretical terms, such as light and space preserve their meanings across revolutions. In addition to classic work by Kuhn, we shall consider approaches that were inspired by Kuhn''s work. In particular, we will consider the approaches of sociologists of scientific knowledge. The course is taught as a seminar in which the students play an active role in presenting and discussing the readings.', 'HPS350H1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS455H1', 'Well-being and Policy Analysis', '24L', 'The research seminar will consider some central questions in the philosophy of economics and political philosophy and their intersection with, and relevance for questions concerning social justice, the environment, well-being, and policy analysis. The aim is to provide some background and analytical tools for policy analysis concerning issues related to well-being, distributive justice, poverty, disability, and environmental sustainability.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 0.5, "department": "HPS"}]}'::jsonb),
    ('HPS480H1', 'Special Topics in History and Philosophy of Science and Technology', '24S', 'This course will focus on matters of special interest in the history and philosophy of science and technology. Topics will change each time the course is offered, but may include a focus on specific-time periods, fields and methods of inquiry, individuals, institutions, geographic regions, controversies, etc.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.5, "department": null}]}'::jsonb),
    ('HPS485H1', 'Special Research Opportunity in HPS', '24L', 'This course offers advanced undergraduate students the opportunity to undertake original research in the history and/or philosophy of science, technology, or medicine, under the guidance of a faculty mentor. Of particular value to students interested in graduate study.', null, null, null::jsonb),
    ('HPS495Y1', 'Individual Studies', null, 'This course offers advanced undergraduate students the opportunity to undertake a reading and/or research project in HPS, supervised by a faculty member in the history and/or philosophy of science, technology, or medicine. Of particular value to students interested in graduate study.', null, 2, null::jsonb),
    ('HPS496H1', 'Individual Studies in HPS', null, 'This course offers advanced undergraduate students the opportunity to undertake a reading and/or research project in HPS, supervised by a faculty member in the history and/or philosophy of science, technology, or medicine. Of particular value to students interested in graduate study.', null, null, null::jsonb),
    ('HPS497H1', 'Individual Studies', null, 'A reading and research project in some aspect of the social, cultural or intellectual history of science and technology, supervised by a faculty member.', null, null, null::jsonb),
    ('HST209H1', 'Introduction to Social Determinants of Health', '36L', 'A multidisciplinary approach to understanding non-medical factors that influence health, health equity, and primary health care. Themes include critical discussion of the measurements of health outcomes and the socioeconomic and political factors that affect health inequities, including neglected and marginalized populations in Canada and globally.', null, 3, null::jsonb),
    ('HST211H1', 'Health Policy in Canada', '24L', 'Introduces students to health policy in Canada, with a particular focus on the social determinants of health, and on how to improve health through policy advocacy. Examines the policy making process in the Canadian context, and the development of health policy in Canada. Explores current debates about health issues.', null, 3, null::jsonb),
    ('HST250H1', 'Introduction to Quantitative Methods in Public Health', '36L', 'This course offers students in Health Studies a basic understanding of the principles of quantitative research methods in health research, including research design, data collection, and analyses. Considerations such as validity, generalizability, and representativeness of data will be addressed. Topics may include experimental, comparative, and epidemiological approaches.', null, 3, null::jsonb),
    ('HST253H1', 'Introduction to Qualitative Methods in Public Health', '36L', 'This course offers Health Studies students a basic understanding of the principles of qualitative health research - which are critical to contextualizing the health practices, experiences, and outcomes amongst diverse populations. Qualitative research methods will examine research design, data collection, and interpretation in using various methodological approaches such as interviews, focus groups, observation, and case studies.', null, 3, null::jsonb),
    ('HST305H1', 'Perspectives in Health, Gender, Ethnicity and Race', '24L', 'This course will examine historical and contemporary health disparities with respect to gender, ethnicity, and race. Other intersectional issues such as Colonialism, class, sexuality, and the urban/rural divide will also be considered as they to social determinants of health. Attention will be focused on examples of disparities that perpetuate and exacerbate current epidemiological challenges for underrepresented populations in Canada and globally.', null, 3, '{"operator": "OR", "items": ["HST250H1", "STA220H1", "STA288H1", "GGR207H1", "EEB225H1"]}'::jsonb),
    ('HST306H1', 'Health, Nutrition and Food Security', '24L', 'This course examines the antecedents (for example: social structure, environments, human development and behaviour) that underlie nutrition-mediated aspects to human health and disease. This will include review and analysis of seminal, primary, and current research as well as contemporary issues surrounding nutritional literacy and deficits, food insecurity and access, as these relate to morbidity and pre-mature mortality. The course will also examine existing public health practices for health promotion and access, and population-level disease prevention and interventions.', null, 3, '{"operator": "OR", "items": ["HST250H1", "STA220H1", "STA288H1", "GGR207H1", "EEB225H1"]}'::jsonb),
    ('HST307H1', 'Special Topics in Public Health I', '24L', 'The specific content of this course will vary from one year to another, depending on the availability of particular health researchers and scholars. Specific course information will be available on the Public Health/Health Studies website at www.uc.utoronto.ca/programs-study-academic-programs-public-health-healt….', null, null, null::jsonb),
    ('HST308H1', 'Aging and Health', '24L', 'Provides an understanding of the interface between health and aging, and how to maintain wellness in a rapidly aging population. Examines theories of aging, the meaning of health in old age, myths about the health of Canada''s older people, and emerging national and international responses to aging populations.', null, 3, '{"operator": "AND", "items": ["HST209H1", "HST211H1"]}'::jsonb),
    ('HST309H1', 'Special Topics in Public Health II', '24L', 'The specific content of this course will vary from one year to another, depending on the availability of particular health researchers and scholars. Specific course information will be available on the Public Health/Health Studies website at www.uc.utoronto.ca/programs-study-academic-programs-public-health-healt….', null, null, null::jsonb),
    ('HST310H1', 'Critical Health Policy', '24L', 'A critical, in-depth exploration of contemporary health and social issues. Political, social and economic forces at play in Canadian society are examined in relation to specific health issues and policies, in order to understand general societal and system dynamics of evolution and change, and to identify implications for reform efforts.', null, 3, '{"operator": "AND", "items": ["HST211H1"]}'::jsonb),
    ('HST330H1', 'Population Health', '24L', 'Extends students´ understanding of population-based strategies of health promotion in Canada. Topics include: variations in health status as affected by population patterns, class, gender, ethnicity, employment, and family composition; major causes of morbidity and mortality; the concept of "community health", opportunities and constraints facing public policy.', null, 3, '{"operator": "AND", "items": ["HST209H1"]}'::jsonb),
    ('HST350H1', 'Health Research & Practice', '36S', 'For students enrolled in the Health Studies Specialist and Major programs. Students engage in career-planning, presentation, and workshop activities that will prepare them for independent research and practicum projects as well as potential graduate-school applications. Includes, but not limited to, sessions on topic selection and project development, finding a supervisor, ethics and professionalism.', null, null, '{"operator": "AND", "items": ["HST250H1"]}'::jsonb),
    ('HST373H1', 'Epidemiology', '36L', 'Introduces students to the principles and methods of epidemiology. Emphasis on descriptive methods and study design. Computational techniques, measurement problems, and issues that surround the drawing of inferences from area-level or other aggregate data will be discussed.', 'HMB342H1', 5, '{"operator": "AND", "items": ["STA220H1"]}'::jsonb),
    ('HST400Y1', 'Public Health Practicum', '172P/24S', 'For students enrolled in the Health Studies Specialist and Major programs. Individual field placement with a health-related institution or organization, in which the student applies theory and skills to specific projects and/or tasks. Culminates in an oral and written report. Not eligible for CR/NCR option.', null, null, '{"operator": "OR", "items": ["HST350H1", "HST350Y1"]}'::jsonb),
    ('HST405H1', 'Global Migration and Health', '24L', 'Over the past decades, economic globalization, widening socio-economic inequities, conflict, natural disasters, environmental degradation, and, more recently, climate change have combined to become increasingly significant forces shaping global migration fluxes. This course analyzes the impact of migration on the health of those who move and of individuals, communities and entire societies in countries of origin, transit, arrival, and resettlement. It adopts an interdisciplinary approach, incorporating scholarly work from the fields of public health, the social sciences, law, and human rights.', 'HST307H1 (Special Topics in Health Studies I: Globalization, Migration and Health), offered in Winter 2017, Winter 2018, and Winter 2019', 3, '{"operator": "OR", "items": ["HST209H1", "HMB203H1", "HMB303H1"]}'::jsonb),
    ('HST407H1', 'Special Topics in Advanced Public Health I', '24L', 'The specific content of this course will vary from one year to another, depending on the availability of particular health researchers and scholars. Specific course information will be available on the Public Health/Health Studies website at www.uc.utoronto.ca/programs-study-academic-programs-public-health-healt….', null, null, null::jsonb),
    ('HST409H1', 'Special Topics in Advanced Public Health II', '24S', 'The specific content of this course will vary from one year to another, depending on the availability of particular health researchers and scholars. Specific course information will be available on the Public Health/Health Studies website at www.uc.utoronto.ca/programs-study-academic-programs-public-health-healt….', null, null, null::jsonb),
    ('HST410H1', 'Case Studies in Health Policy', '36S', 'Analyses the formation and implementation of health policy through the use of case studies. Each case deals with a substantive health policy issue. Using case studies, students will learn to understand and analyze the processes by which public policies are formed, and perform comparisons of policy alternatives.', null, 3, '{"operator": "AND", "items": ["HST211H1"]}'::jsonb),
    ('HST411H1', 'Political Economy of Health', '36S', 'Examines the production and distribution of health and illness within and across populations. A political economy approach is used to better understand the fundamental origins of health inequalities, the political action that is required to tackle them, and the obstacles that hinder the possibilities for such action.', null, 3, '{"operator": "AND", "items": ["HST209H1"]}'::jsonb),
    ('HST432H1', 'Public Health Policy Engagement and Action', '24S', 'This course emphasizes an understanding of population health research and historical evidence in the development of health policies. We explore whether and how policies are evidence-informed, sustainable, and equitable. Knowledge translation and social justice frameworks will be examined to understand bottlenecks or obstacles for translating evidence into community engagement and action. Students will engage in case study analyses to understand the role of public engagement and action (e.g. private sectors, communities, government, non-profits, etc.) in the evolution of programs and policies.', 'HST407H1 (Public Health Policy Engagement and Action), offered in Fall 2022, 2023, and 2024.', 3, '{"operator": "AND", "items": ["HST211H1"]}'::jsonb),
    ('HST440H1', 'Health & Pharmaceuticals', '24L', 'A critical examination of drug development, including the role of health professionals and the pharmaceutical industry in researching, testing, marketing, licensing, and evaluating pharmaceutical drugs. Topics include the differing needs for drug development, evaluation and dispensing in lower income countries, and potential conflicts of interest in drug development.', null, 3, '{"operator": "OR", "items": ["HST209H1", "HMB303H1"]}'::jsonb),
    ('HST450Y1', 'Undergraduate Research Project in Public Health', null, 'Final culminating project for students in the Health Studies Specialist. Students will prepare an undergraduate thesis by the end of the course under the supervision of a University of Toronto faculty member. Students must submit an Independent Research Course Proposal form confirming a faculty supervisor has agreed to participate and describing the content of the project by the end of August. This form is available on the University College Health Studies Program website at https://www.uc.utoronto.ca/health-studies/courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["HST250H1", "STA220H1", "HST350Y1"]}'::jsonb),
    ('HST451Y1', 'Independent Research in Public Health', null, 'This two-semester course designation will permit students to gain academic credit for health studies pursued independently, or to participate in an ongoing health research project, under the supervision of a University of Toronto faculty member. Students must submit an Independent Research Course Proposal form confirming a faculty supervisor has agreed to participate and describing the content of the project by the end of August. This form is available on the University College Health Studies Program website at https://www.uc.utoronto.ca/health-studies/courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["HST209H1", "HST250H1"]}'::jsonb),
    ('HST464H1', 'The Nature of Global Health', '24L', 'Explores the historical, ideological, economic, political, and organizational factors that shape the theory and practice of international health (IH). Students will be encouraged to critically examine some of the central tensions embedded in this field.', null, 3, '{"operator": "OR", "items": ["HST209H1", "HMB303H1"]}'::jsonb),
    ('HST480H1', 'Independent Research in Public Health', null, 'This one-semester course will permit students to gain academic credit for health studies pursued independently, or to participate in an ongoing health research project, under the supervision of a University of Toronto faculty member. Students must submit an Independent Research Course Proposal form confirming a faculty supervisor has agreed to participate and describing the content of the project at least two weeks prior to the first day of term. This form is available on the University College Health Studies Program website at https://www.uc.utoronto.ca/health-studies/courses. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": ["HST209H1", "HST250H1"]}'::jsonb),
    ('HUN100Y1', 'Elementary Hungarian', '120P', 'This course is aimed at students interested in Hungarian but have no prior knowledge of the language. The course emphasizes essential vocabulary, basic comprehension, speaking, reading and writing skills with a balance between communicative activities and grammar practices. Communicative activities will include group and partner work to encourage interactive learning.', null, 1, null::jsonb),
    ('HUN200Y1', 'Intermediate Hungarian', '96P', 'Review of descriptive grammar; studies in syntax; vocabulary building; intensive oral practice; composition; reading and translation.', null, 1, null::jsonb),
    ('HUN310Y1', 'Advanced Hungarian', '48S', 'This course is intended to build on the skills and knowledge acquired by the students in the previous Hungarian language courses. It will consist of a more advanced study of grammar, more complex vocabulary, higher level of oral skills and longer reading, writing and translation exercises. Communicative activities will include group and partner work to encourage interactive learning.', null, 1, null::jsonb),
    ('HUN320Y1', 'A Survey of Hungarian Literature', '48S', 'A chronological study of the development of Hungarian literature since the 12th century; emphasis both on outstanding writers and on significant movements or themes. Transformations of ideas and changes in language and style. No knowledge of Hungarian required.', null, 1, null::jsonb),
    ('HUN335H1', 'Urban vs. Rural: Immigration to and Settlement in North America', '12L/12S', 'This course will provide an examination of the history of Hungarian Immigration to and settlement in North America. The course will examine the "push" and "pull" factors, the socio-economic factors involved, their patterns of migration and the organizational development of the communities they founded in North America.  The course will compare and contrast the reception the immigrants and later refugees received in the United States and Canada and examine how they adapted to their new homelands.', null, 3, null::jsonb),
    ('HUN345H1', 'The Dynamic of Hungarian Culture, Ethnography, and Folklore', '12L/12S', 'Explore the cultural traditions, historical processes, myths, and figures that have shaped and redefined Hungarian civilization and national identity. Theoretical and practical classes on ethno-genesis, anthropology, and folklore. Readings in English (also available in Hungarian).', null, 1, null::jsonb),
    ('HUN355H1', 'One Hundred Years of Dramatic Change: History of the Past Century and Reflections of Society in Hungarian Culture', '12L/12S', 'Explore Hungary''s rapidly changing place in Europe. Focus on political, sociological, and historical understandings of nationalism and identity as they manifest themselves in literature, history, and culture. Knowledge of Hungarian not required.', null, 3, null::jsonb),
    ('HUN455H1', 'Hungary and Europe: Cultural Adaptation in the Late 20th Century', '12L/12S', 'Focus on literature, art, mass media, and popular culture in post-1990 Hungary with special emphasis on the past ties to European culture and the impact of European integration. Readings in English (also available in Hungarian).', null, 1, null::jsonb),
    ('HUN497Y1', 'Independent Study (Hungarian)', null, 'Translation course concentrating on Hungarian prose translation. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HUN498H1', 'Independent Study (Hungarian)', null, 'Translation course concentrating on Hungarian prose translation. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IFP100H1', 'Themes in World History', '24L', 'Surveys the development of human societies from their origins to the present. Topics may include the environment, cultural development and interaction, the creation and nature of belief systems, political, economic and social structures, gender relations, and the relationship between global patterns and local development. Restricted to students enrolled in the summer offering of the International Foundation Program (IFP). Not eligible for CR/NCR option.', 'IFP100Y1/ UTP100H1', 3, null::jsonb),
    ('IFP100Y1', 'Themes in World History', '48L/36T', 'Surveys the development of human societies from their origins to the present using examples from across the world. Topics may include the environment, cultural development and interaction, the creation and nature of belief systems, political, economic and social structures, gender relations, and the relationship between global patterns and local developments. Enrolment is restricted to students registered in the International Foundation Program. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('IMM199H1', 'Immunology in the News Today', '24S', 'Why do we get sick? How do vaccines work? Does our diet influence our immunity? This course is intended to inspire curiosity about questions generated by immunology concepts that are prevalent in the news today. Different topics will be explored each week including immunity worldwide, human vaccinations and the mucosal immune system. Topics will be placed in context through real-life case studies, immunology virtual laboratory simulation, interactions with faculty members and extensive coverage of the basic science underlying each topic. Restricted to first-year students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('IMM221H1', 'Origins of Immunology', '24L/12T', 'This course will examine the milestones in the field of immunology from ancient to current times, with specific emphasis on 1880 to 1980. It will observe how the concept of immunity has changed over time and examine the major events and discoveries that shaped how immunology is viewed today. Pioneers, such as Edward Jenner, Louis Pasteur, Robert Koch, Paul Ehrlich and Brigitte Askonas, and their contributions to the field will be discussed in both historical and scientific context as well as their impact on society. Assignments are staggered for students to build upon instructor''s feedback.', null, 3, null::jsonb),
    ('IMM250H1', 'The Immune System and Infectious Disease', '24L', 'Students will be introduced to the basic concepts of immunity to infectious disease and how breakdown of the immune response can lead to auto-immunity. We will trace the history of current ideas in immunology and the immune response by examining how bacteria and viruses cause disease and the initial discoveries that led to such developments as vaccination. Current topical and newsworthy infectious diseases (HIV, tuberculosis, SARS, avian flu) will be used as examples of how the immune system copes with microbial infections.', null, 4, null::jsonb),
    ('IMM299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IMM299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IMM340H1', 'Fundamental Immunology', '24L/12T', 'This course introduces the basic principles and key players of the immune system: differences and interplay between innate and adaptive immunity, how immune cells develop and function, how immune cells recognize threats and danger and mount an appropriate and measured response.', 'IMM341H1', 4, '{"operator": "AND", "items": ["BIO230H1"]}'::jsonb),
    ('IMM341H1', 'Fundamental Immunology (Advanced)', '24L/12T', 'This course introduces the fundamental principles and key players of the immune system: differences and interplay between innate and adaptive immunity, how immune cells develop and function, how immune cells recognize threats and danger and mount an appropriate and measured response. Intended for students specializing in Immunology and related programs.', 'IMM340H1', 4, '{"operator": "AND", "items": ["BIO230H1"]}'::jsonb),
    ('IMM350H1', 'The Immune System in Action', '24L/12T', 'This course illustrates how different elements of the immune system come together to mount efficient and measured responses. Topics include response to infectious microorganisms, allergy and autoimmunity, immune responses against cancer, and transplantation immunology.', 'IMM351H1', 4, '{"operator": "OR", "items": ["IMM340H1", "IMM341H1"]}'::jsonb),
    ('IMM351H1', 'The Immune System in Action (Advanced)', '24L/12T', 'This course illustrates how different elements of the immune system come together to mount efficient and measured responses. Topics include response to infectious microorganisms, allergy and autoimmunity, immune responses against cancer, and transplantation immunology. Intended for students specializing in Immunology and related programs.', 'IMM350H1', 4, '{"operator": "OR", "items": ["IMM341H1", "IMM340H1"]}'::jsonb),
    ('IMM360H1', 'Scientific Methods and Research in Immunology', '24L/24T', 'This course will provide students with an opportunity to advance their understanding of research in Immunology in accordance with scientific methodology. Students will critically appraise scientific articles, design and analyze scientific experiments, and develop the core skills of data and statistical literacy. This course is well suited for anyone interested in discovering knowledge in Immunology, providing students with a methodology for the achievement of scientific research activities.', null, 4, '{"operator": "AND", "items": ["IMM250H1", {"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["BIO260H1", "HMB265H1"]}, {"operator": "OR", "items": ["STA288H1", "STA220H1"]}]}'::jsonb),
    ('IMM385Y1', 'Special Research Project in Immunology', '180P', 'This course provides an opportunity for students to conduct a research project under the supervision of a member of the Faculty. Students are expected to devote a minimum of seven hours per week to the course from the week the fall term lectures begin to the last week of the spring term. Research projects will involve experimental design and work, data analyses, literature reading etc.', null, 4, '{"operator": "AND", "items": ["IMM250H1"]}'::jsonb),
    ('IMM428H1', 'Molecular Immunology', '24L', 'This course will focus on the molecular and cellular biology of immune recognition. The course will emphasize historical and recent experimental evidence leading to our current understanding of immune recognition. Subtopics are subject to change and have recently included mechanisms of diversification of immunoglobulin receptors, T cell –MHC interactions, T cell activation and signaling mechanisms; receptors of the innate immune system, immune recognition by natural killer cells.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["BCH311H1", "CSB349H1", "MGY311Y1", "PSL350H1"]}, {"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}]}'::jsonb),
    ('IMM429H1', 'Developmental Immunology', '24L', 'Hematopoiesis, myelopoiesis, lymphopoiesis, a study of the development of cells involved in the immune system including their ontogeny, physical, molecular, and biochemical characteristics, regulation of differentiation and maturation, positive and negative selection of lymphocytes.', null, 4, '{"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}'::jsonb),
    ('IMM430H1', 'Clinical Immunology', '24L/24T', 'This course will address the underlying pathogenesis as well as highlight the challenges of treating immune-related conditions such as autoimmunity, cancer, HIV, and transplantation and graft rejection. Half of the lectures will address the genetics and cellular pathogenesis of autoimmune diseases such as multiple sclerosis, type I diabetes and lupus. Other lectures will overview a number of immunological challenges faced in the clinic, such as preventing graft rejection after transplantation or boosting the immune system to fight cancer and HIV.', null, 4, '{"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}'::jsonb),
    ('IMM431H1', 'Immunotherapy', '24L/12T', 'Therapies that enhance, or suppress, the body''s immune response have proven remarkably efficient for the treatment of human diseases such as cancer, autoimmunity and chronic inflammation. Some of these therapies, such as the so-called checkpoint inhibitors and CAR-T cell therapies have recently leaped from bench to bedside. This course will cover the fundamental immune principles at play, how they were discovered, as well as the existing and future immune therapies to treat these diseases.', null, 4, '{"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}'::jsonb),
    ('IMM432H1', 'Case Studies in Autoimmune Diseases', '36S', 'Understanding autoimmune diseases and identifying molecular targets that either slow or stop disease progression is critical for the development of novel and effective therapies that improve patient quality of life. This course will use case-based learning and an interactive seminar format to provide an advanced overview of autoimmune diseases and their treatments, and will include the in-depth study of selected autoimmune diseases highlighting the patient''s perspective.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["IMM340H1", "IMM341H1"]}, {"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}]}'::jsonb),
    ('IMM433H1', 'Neuroimmunology', '24L', 'This course will provide students with an opportunity to advance their understanding of the emerging interdisciplinary research in Neuroimmunology. Topics covered include neural regulation of immune cells and lymphoid organs, and the reciprocal immune-mediated regulation of the central and peripheral nervous system. An in-depth analysis of microglial cells, meningeal immunity, as well as peripheral immunity will be discussed in the context of neurodevelopmental and neurodegenerative diseases.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["IMM340H1", "IMM341H1"]}, {"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}]}'::jsonb),
    ('IMM435H1', 'Practical Immunology', '72P', 'Application of basic principles acquired from  IMM350H1/ IMM351H1; immunological procedures performed in research and diagnostic laboratories using molecular and cellular approaches; instruction through lectures, video tapes, and practical exercises in the laboratory. (Lab Materials Fee: $50)', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1"]}, {"operator": "OR", "items": ["IMM350H1", "IMM351H1"]}]}'::jsonb),
    ('IMM450Y1', 'Research Project in Immunology', '154P', 'An opportunity for specialized research in Immunology under the supervision of a member of the Faculty. There are no pre- or co-requisites, although preference is given to Immunology Specialist and Major students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('INI100H1', 'The City Where Movies Are Made', '36S', 'In this course, first-year students will be introduced to film culture in Toronto from a variety of angles, including: a history of the city onscreen (both as itself and as a popular shooting location for American productions); an account of major Toronto filmmaking sites and institutions; introductions to local directors and producers; and overviews of contemporary local film festival culture (TIFF and beyond) as well as the city''s film-critical community. Through a combination of lectures, screenings, field trips and special guest speakers, the students will be moved to consider both the vitality of Toronto''s film scene as well as its connections to other aspects of the city. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('INI101H1', 'Writing, Advocacy, and Social Media', '36S', 'An introduction to the concept of the city as a creative environment promoting not only growth and wealth but also social justice, equality, cooperation, and civility. Students will learn to build their own writing practice to help them to observe, interpret, and reflect upon the process of urban interaction and the relationship between creativity and justice. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('INI102H1', 'Storytelling Through Creative Nonfiction', '36S', 'An introduction to creative writing techniques and various forms of creative nonfiction (personal essay, biographical essay, flash nonfiction, lyric essay, visual essay, and other experimental forms) through which students will explore and develop their conscious connection to the natural-urban landscape. The course will include activities such as field trips, readings, interviews, and journaling to generate the material for essays on engagement with nature in the city. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('INI105H1', 'Nature and the City', '36S', 'This course introduces first-year students to nature in the city from a variety of perspectives: from contemplative to activist discourse, private gardens to public parks, and biodiversity to inequality. Through texts, images, films, and field trips, students will figuratively and literally explore the city and its relationship to the natural, the wild, and other contested ideas. Students write weekly journals in response to the course materials from which they develop a term project that focuses on an aspect of nature in the city.', null, 1, null::jsonb),
    ('INI106H1', 'Storytelling through Literary Journalism', '36S', 'An introduction to literary journalism, in which students study the craft of storytelling along with interviewing, reporting, and the journalist''s ethical stance. Guest speakers, field trips, writing activities and course readings will help students engage deeply with their environment and develop the skills and sensitivity required for literary reporting. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('INI196H1', 'Environmental Writing', '24L', 'From environmental disasters and ecological collapse to climate change denial and celebrations of nature and wilderness, we will explore the diverse ways humans imagine and write about the natural world and the consequences of such writing. We will study a variety of nonfiction texts, images, and videos about ecology, the environment, nature, wilderness, and sustainability as we consider what these terms mean. From the 19th century American transcendentalists to 20th century ecologists, and 21st century scientific, Indigenous, feminist, and anti-racist perspectives, we will analyze the many ways that humans use writing to argue for certain ways of seeing and interacting with our planet and the creatures that inhabit it. Through weekly reading, written reflections, and discussion, students will hone their deep reading, research, and writing skills. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('INI299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('INI399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('INS110H1', 'Introduction to Conversational Anishinaabemowin', '36L', 'This course will introduce students to Anishinaabemowin, the language of the Anishinaabe people (an Indigenous people of the Great Lakes), with a focus on greetings and basic conversation. The course is highly interactive and will engage students in dialogues that reflect real-life uses while also introducing them to nuances in how the language functions in different settings. This course is intended to give students some speaking skills along with an appreciation for the importance of the language to Anishinaabe communities. While the course is appropriate for Indigenous Studies majors, it is accessible to students from other units as well.', 'INS210Y1,  INS310Y1', 3, null::jsonb),
    ('INS200H1', 'Introduction to Indigenous Truth and Resilience', '24L/12T', 'This course is an interdisciplinary introduction to the historical and contemporary experiences of Indigenous peoples in Canada, with an emphasis on local lands and peoples. The course will explore Indigenous resilience, relationships with settlers and settler states, and principles and ethics of Indigenous Knowledge. Tutorials will focus on critical discussion and experiential learning.', null, 3, null::jsonb),
    ('INS201H1', 'Introduction to Indigenous Studies: Foundations', '24L/12T', 'This course is designed to introduce students to the ideas, methods and themes of the discipline of Indigenous Studies. The course will explore the development of the field of Indigenous Studies in Canada. Topics will include explorations into Indigenous thought, philosophies, knowledge systems, and ways of being. The focus will be on North America with comparative discussions of Indigenous peoples and their experiences from other parts of the world.', 'INS201Y1', 3, null::jsonb),
    ('INS202H1', 'Introduction to Indigenous Studies: History & Politics', '24L/12T', 'This course is designed to introduce students to Indigenous history and politics as they inform the field of Indigenous Studies. The course will provide an overview of the history and politics of Indigenous peoples in Canada. Topics will include Indigenous creation stories, Indigenous treaty-making traditions, settler contact and conflict, history of education, Indigenous rights within the Canadian State and contemporary issues such as food sovereignty, language revitalization, arts, and international relations. The focus will be on North America with comparative discussions of Indigenous peoples and their experiences from other parts of the world.', 'INS201Y1', 3, null::jsonb),
    ('INS205H1', 'Indigenous Worldviews, Spiritual and Healing Traditions', '24L', 'This course will discuss the relationship between spiritual philosophies, beliefs, traditions and practices that contribute to meaning in Indigenous communities. This course will emphasize traditions and teachings and understanding the role of spirituality historically and within contemporary Indigenous societies, including governance, treaties, environment, culture, healing and everyday life.', null, 2, '{"operator": "OR", "items": ["INS200H1", "INS201Y1", "INS201H1", "INS202H1"]}'::jsonb),
    ('INS210Y1', 'Introduction to Anishinaabemowin', '72L', 'An introduction to the Anishinaabe language.', null, 1, null::jsonb),
    ('INS215Y1', 'Introduction to an Indigenous Language of Canada', '72L', 'This course will offer an introduction to one of Canada''s Indigenous languages, including its writing system. Speaking skills will be emphasized.', 'ABS215H1;  ABS215Y1', 1, null::jsonb),
    ('INS220Y1', 'Introduction to Kanien''kéha (Mohawk Language)', '72L', 'An introduction to Kanien''kéha (Mohawk Language), a member of the Iroquoian language family.', null, 1, null::jsonb),
    ('INS230H1', 'Introduction to Inuktitut', '24L', 'An introduction to one dialect of Inuktitut, the language of the Inuit, including aspects of other dialects and the syllabic writing system.', 'ABS230H1', 1, null::jsonb),
    ('INS231H1', 'Elementary Inuktitut', '24L', 'This course builds on the introduction to Inuktitut from ABS230H. Emphasis will be placed on developing grammatical complexity and vocabulary in students oral skills, as well as dialect and cultural awareness.', 'ABS231H1', 1, '{"operator": "AND", "items": ["INS230H1"]}'::jsonb),
    ('INS240Y1', 'Ecological Interactions: Intro to Indigenous and Western Sciences', '72L/72P', 'Introduction to methodologies and applications of Indigenous and Western sciences, with an emphasis on environmental change, animal behaviour, evolution, sustainable practices, and implications of intrinsic ecological connections. Exploratory labs, often outdoors, develop literacy and skills in each paradigm as well as critical thought, creative reflection, and synthesis of knowledge.', 'ABS240Y1', 4, '{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}'::jsonb),
    ('INS250H1', 'Introduction to Indigenous Environmental Studies', '24L', 'This course is an examination of Indigenous environmental knowledge and practices. The course provides an overview of Indigenous peoples'' relationships with the natural world and a range of environmental issues, including climate change, water governance and Indigenous approaches to conservation and ecological restoration. Drawing on examples of Indigenous-led research, activism and policy, the course explores a range of topics in the field of Indigenous environmental studies through readings, lectures, films, and creative works.', null, 3, '{"operator": "OR", "items": ["INS201Y1", "INS201H1", "INS202H1"]}'::jsonb),
    ('INS261H1', 'Contemporary Challenges Facing Indigenous Communities', '24L', 'This is a survey course focusing on the contemporary challenges faced by Indigenous peoples in Canada. In this course students research specific challenges facing Indigenous communities today. This includes specific challenges that arise out of the broader topic areas of language and culture, land rights, economics, governance, youth, education, health, social services, environment, violence, healing, community development, repatriation of cultural property, and decolonization.', null, 3, '{"operator": "OR", "items": ["INS201Y1", "INS201H1", "INS202H1"]}'::jsonb),
    ('INS300Y1', 'Worldviews, Indigenous Knowledges, and Oral Tradition', '48L', 'A study of the languages and culture of Indigenous peoples through exploration of oral histories, from creation stories until present times, including the role of oral history and methods for studying oral history through accounts told by elders.', null, 1, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS301Y1', 'Indigenous Languages and Cultures', '48L', 'Examination of the historical interplay of Indigenous languages and cultures in Canada. Particular focus is on the languages and cultures of Indigenous peoples of the Great Lakes.', null, 1, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS302H1', 'Indigenous Representation in the Mass Media and Society', '24L', 'A survey of historical and contemporary representations of Indigenous people in the mass media. Introduction to basic techniques for evaluating, analyzing, and understanding the construction of Indigeneity as it is communicated through film, television, and other media. Examination of racial stereotypes and the role of mass communication in perpetuating and challenging stereotypes, cultural appropriation, Indigenous media production, impact of media portrayal of Indigenous peoples.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS303H1', 'Understanding Indigenous Language Vitality and Endangerment', '24S', 'There is a broad consensus among Indigenous communities and within scholarly discourse concerning the profound and inseparable connection between Indigenous languages and Indigenous ways of knowing and being. This course will begin by examining the centrality of Indigenous languages to Indigenous peoples, as well as their broader societal significance. Building upon this foundation, the course will critically investigate the various factors contributing to Indigenous endangerment and vitality, both within Canada and internationally. Through this exploration, students will engage in a comprehensive analysis of the challenges and strategies associated with Indigenous language revitalization.', null, 1, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS304H1', 'Best Practices in Indigenous Language Revitalization', '24L', 'Building on the foundational concepts and issues surrounding Indigenous endangerment and vitality introduced in  INS303H1, this course provides an in-depth exploration of the challenges, opportunities, and strategies for Indigenous language revitalization (ILR) at both community and national levels. Focusing on language policy, planning, and best practices in revitalization, this course will examine a wide range of social, political, and linguistic factors that influence language use, particularly within Indigenous communities in Canada but also globally.', null, 1, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS310Y1', 'Anishinaabemowin II', '72L', 'Further study of the Anishinaabe language with emphasis on speaking and writing.', 'ABS310Y1', 1, '{"operator": "AND", "items": ["INS210Y1"]}'::jsonb),
    ('INS320Y1', 'Kanien''kéha II', '72L', 'Further study of Kanien''kéha (Mohawk Language), a member of the Iroquoian language family.', 'INS323Y1', 1, '{"operator": "AND", "items": ["INS220Y1"]}'::jsonb),
    ('INS322H1', 'Indigenous Narratives of Empowerment', '24L', 'This course explores Indigenous decolonization and empowerment by analysing comparatively theoretical and literary debates that focus on issues of sovereignty, gender, grass-roots activism, and anti-racism. It analyses several emerging paradigm approaches to this set of debates including intersectional critical-race theory, Indigenous feminisms, and decolonization practices in theoretical and literary texts.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS331H1', 'Indigenous Music: Technical and Theoretical Aspects', null, 'Contemporary and historical musical theory of sacred spiritual ceremonial music and social-public performance practices of Indigenous people of North America. This course will have a participatory emphasis on the music of the Haudenosaunee (Longhouse People ) of the Great Lakes.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS340Y1', 'Indigenous Health Science', '48L/48P', 'This course is themed in six-week quarters addressing four aspects of Western Science (basic, applied, clinical and population health). Within each quarter, the Western Science theme is examined holistically using Indigenous Science and the four aspects of the Medicine Wheel (physical, mental, emotional, spiritual).', null, 4, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS341H1', 'North American Indigenous Theatre', '24L', 'An introduction to the evolution of Indigenous theatre in North America, examining traditional oratory, ceremony, community responsibility, and social construct and their impact on current Indigenous theatre.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS350H1', 'Indigenous Health Systems', '24L', 'An overview of Indigenous health systems, internationally, nationally, provincially and locally, with a focus on Ontario. Discussion of health models and strategies, policy, legislation, jurisdictional issues, Indigenous health initiatives.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}, "INS200H1"]}]}'::jsonb),
    ('INS352H1', 'Indigenous Leadership, Policy and Practices in Canada', '24L', 'A historical and contemporary overview of leadership and politics in First Nation, Inuit and Metis communities in Canada. This course will focus on pre-contact governance structures, contemporary effects of colonization, and processes and strategies for decolonization. Various policy initiatives from Indigenous organizations will be examined.', null, 3, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS353H1', 'First Nations Politics in Canada', '24L', 'This course examines recent trends in First Nations politics and their effects on the social, economic and political lives of First Nations Peoples. It provides students with an in-depth understanding of the socio-political and cultural context for First Nations societies in contemporary settings. It explores the legacies of the Indian Act, the tabling of the 1969 White Paper and responses to it, the emergence of current Indigenous political movements, Constitutional issues, and First Nations citizenship.', null, 3, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS354H1', 'Indigenous Governance and Self-Determination', '24L', 'This course examines the theory and practice of Indigenous governance and self-determination in Canada and abroad. It studies forms of Indigenous governance and self-determination past, present and future, with a special section on Indigenous self-government agreements in Canada.', 'ABS354H1', 3, '{"operator": "AND", "items": ["INS353H1"]}'::jsonb),
    ('INS355H1', 'Current Issues in Indigenous Health', '24L', 'This course will examine current views about Indigenous peoples'' health. The course will focus on Indigenous peoples'' perceptions of health and contemporary health systems, including policy, politics and practices.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS360Y1', 'Politics and Process of Reconciliation in Canada', null, 'This course uses relationship-building methodologies to develop skills to examine and explore the concept and processes, practice and promises of reconciliation. Through class discussion/seminars, guest speakers, and comparative readings in: Canadian and Indigenous colonial history; the findings of the Canadian Truth and Reconciliation Commission; Canadian Human Rights Tribunal Decisions; and Indigenous solidarity movements in Canada. Students will examine reconciliation and determine whether it is a different process than ''decolonization''.', null, 3, '{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}'::jsonb),
    ('INS371H1', 'Topics in Indigenous Literatures', '24S', 'This seminar provides an in-depth examination of Indigenous literatures in a comparative context. Content in any given year depends on the instructor. See Indigenous Studies website for more details.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}]}'::jsonb),
    ('INS372H1', 'Special Topics in Indigenous Language', '36S', 'This seminar provides an in-depth examination of Indigenous language revitalization efforts in Canada and internationally. Content in any given year depends on the instructor. See Indigenous Studies website for more information.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"operator": "OR", "items": ["INS210Y1", "INS220Y1", {"operator": "AND", "items": ["INS230H1", "INS231H1"]}]}]}'::jsonb),
    ('INS380H1', 'Special Topics in Indigenous Studies', '24L', 'This seminar provides an in-depth examination of trends and topics within Indigenous Studies. Content in any given year depends on the instructor. See Indigenous Studies website for more detail.', null, null, '{"operator": "AND", "items": [{"credits": 5.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS390H1', 'Research and Ethics in Indigenous Studies', '24S', 'This course examines research approaches, strategies, methods and techniques used in Indigenous studies. It explores a range of topical issues including research ethics and protocols, intellectual property rights, research agreements and community-based research. This course includes the study of quantitative, qualitative and Indigenous methodologies. Critically examines research theories, methodologies and practices used by academic disciplines to study Indigenous peoples. Decolonized research methodologies will form a focus of this course.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}]}'::jsonb),
    ('INS398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}]}'::jsonb),
    ('INS402H1', 'Traditional Indigenous Ecological Knowledge', '36L', 'An overview of the relationships between Indigenous peoples and their environments, including an exploration of cultural, historical, and contemporary aspects of Indigenous environmental philosophies; the nature, control and transmission of Traditional Ecological Knowledge (TEK), and historical uses of TEK in managing the environment.', null, 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS403H1', 'Indigenous Peoples and the Urban Context', '24S', 'Critically examines Indigenous peoples'' experiences, encounters and interactions in urban areas in Canada. This course explores the historical and contemporary conditions of Indigenous peoples, including urban governance and the development of Indigenous organizations. This course will focus on youth perspectives and how traditions, cultures and knowledges are expressed in urban settings.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS405H1', 'Indigenous Thought & Expression: Creative Non-fiction', '24S', 'An investigation of (Anishnaabe, Iroquoian, Athapaskan, Salish), examined through the study of research and writing of creative-nonfiction.', null, 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS406H1', 'Indigenous Makers Studio', '36L', 'In this course students will create pieces of material culture reflective of Indigenous knowledge values and principles with a focus on producing utilitarian items. Students will journal about their creative process and provide an artist''s statement for each item created in the course. Assessment will be based on a combination of written submissions and created pieces. Specific projects may include sewing, quilting, beadwork, pottery, basketry, etc.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS407H1', 'Indigenous Environmental Justice', '36L', 'In this course, we will examine how Indigenous land and water governance have been impacted by colonial policies and extractive capitalist developments. We will discuss how Indigenous peoples negotiate and resist such impacts while also renewing responsibilities with land, water, and animal and plant relations. The course is primarily focused on the North American context, with many case studies taking place in Canada.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"operator": "OR", "items": [{"credits": 2.0, "department": "INS"}, "GGR321H1"]}]}'::jsonb),
    ('INS410H1', 'Anishinaabewin Intellectual Traditions, Narrative and Culture', '24S', 'An examination of oral narratives with an emphasis on the significance of language. This course will give students an in-depth understanding of Anishinaabewin philosophies, teachings and values.', 'INS404H1', 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS411H1', 'Advanced Anishinaabemowin', '36L', 'This course will allow students to further their speaking and writing skills in Anishinaabemowin after completing the two levels of foundational grammar and speaking. The course is highly interactive and will engage students in speaking with advanced language speakers. Students will produce advanced language written and audio materials such as scripts, podcasts, short stories, etc. Assessments will include individual and group projects in written and oral forms.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, "INS210Y1", "INS310Y1"]}'::jsonb),
    ('INS460H1', 'Indigenous Theory, Research and Methods', '36L', 'This course explores the basis of Indigenous knowledge and how that translates into research theory and methodology. Students will design a research project, consider Indigenous research governance and conduct an ethics review. This is a service learning course. This course is only open to students enrolled in a Specialist or Major in Indigenous Studies.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, "INS390H1", {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INS480H1', 'Advanced Special Topics in Indigenous Studies', '24L', 'This seminar provides an advanced in-depth examination of trends and topics within Indigenous Studies. Content in any given year depends on the instructor. See Indigenous Studies website for more detail.', null, 1, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS491Y1', 'Topics in International Indigenous Studies', '48S', 'This seminar provides an in-depth examination of Indigenous studies in international contexts. Content in any given year depends on the instructors. See Indigenous Studies website for more detail. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS492H1', 'Topics in International Indigenous Studies', '24S', 'This seminar provides an in-depth examination of Indigenous studies in international contexts. Content in any given year depends on the instructors. See Indigenous Studies website for more detail. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 2.0, "department": "INS"}]}'::jsonb),
    ('INS493H1', 'Independent Experiential Studies', null, 'Students design and implement an independent experiential Indigenous studies research project in consultation with an Indigenous organization and a faculty supervisor. Students must be enrolled in a major or specialist program in Indigenous Studies, and require written permission from a faculty supervisor and the Director of Indigenous Studies. Not eligible for CR/NCR option.', 'ABS493H1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "INS390H1"]}'::jsonb),
    ('INS494Y1', 'Independent Experiential Studies', null, 'Students design and implement an independent experiential Indigenous studies research project in consultation with an Indigenous organization and a faculty supervisor. Students must be enrolled in a major or specialist program in Indigenous Studies, and requires written permission from a faculty supervisor and the Director of Indigenous Studies. Not eligible for CR/NCR option.', 'ABS494Y1', null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "INS390H1"]}'::jsonb),
    ('INS495Y1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and the supervisor before enrolment in the course. Available only when someone is willing and able to supervise. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
