    ('INS498Y1', 'Independent Research', null, 'Supervised independent research on a topic agreed on by the student and the supervisor before enrolment in the course. Available only when someone is willing and able to supervise. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, {"credits": 1.0, "department": "INS"}]}'::jsonb),
    ('INT200H1', 'Arts & Science Internship Program - Professional Work Term', null, 'Students participate in a full-time, paid, career-related work experience totalling at least 420 hours within a 4-month period. Students compete for employment within the public, not-for-profit, or for-profit sectors. Students will be enrolled into the course once hired for an ASIP work term and the work experience must be approved by the Experiential Learning & Outreach Support (ELOS) Office. Student performance while on the work term will be monitored through a site visit and/or student and employer check-in. Students will be required to submit a learning plan at the start of each work term opportunity, reflective reports at regular intervals during the work period, a work term evaluation, and a final work term assignment (which may have different formats depending on the student''s program). Employers will also be asked to submit a final evaluation of the student''s progress and performance. This course does not carry credit weight, is evaluated as Credit/No Credit, and no tuition fee is associated. This course is only open to students admitted to the ASIP stream of their program of study for Year 2.', null, null, '{"operator": "AND", "items": ["PDC221H1"]}'::jsonb),
    ('INT300H1', 'Arts & Science Internship Program - Professional Work Term', null, 'Students participate in a full-time, paid, career-related work experience totalling at least 420 hours within a 4-month period. Students compete for employment within the public, not-for-profit, or for-profit sectors. Students will be enrolled into the course once hired for an ASIP work term and the work experience must be approved by the Experiential Learning & Outreach Support (ELOS) Office. Student performance while on the work term will be monitored through a site visit and/or student and employer check-in. Students will be required to submit a learning plan at the start of each work term opportunity, reflective reports at regular intervals during the work period, a work term evaluation, and a final work term assignment (which may have different formats depending on the student''s program). Employers will also be asked to submit a final evaluation of the student''s progress and performance. This course is only open to students admitted to the ASIP stream of their program of study for Year 2. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details.', 'INT301H1', null, '{"operator": "AND", "items": ["PDC321H1"]}'::jsonb),
