    ('INT471H1', 'Arts & Science Internship Program - Professional Work Term', null, 'Students participate in a full-time, paid, career-related work experience totalling at least 420 hours within a 4-month period. Students compete for employment within the public, not-for-profit, or for-profit sectors. Students will be enrolled into the course once hired for an ASIP work term and the work experience must be approved by the Experiential Learning & Outreach Support (ELOS) Office. Student performance while on the work term will be monitored through a site visit and/or student and employer check-in. Students will be required to submit a learning plan at the start of each work term opportunity, reflective reports at regular intervals during the work period, a work term evaluation, and a final work term assignment (which may have different formats depending on the student''s program). Employers will also be asked to submit a final evaluation of the student''s progress and performance. This course is only open to students admitted to the ASIP stream of their program of study for Year 3. This course does not carry credit weight, is evaluated as Credit/No Credit, and no tuition fee is associated.', 'INT470H1', null, '{"operator": "AND", "items": ["INT451H1"]}'::jsonb),
    ('IRE199H1', 'Why We Work: Understanding Work Through the Prism of Art & Culture', '24S', 'Why do we work? What does work mean to the average person? These questions are not as straightforward as they appear. We work for the bulk of our lives and most of our days are spent with coworkers who are neither family nor our closest friends, but we often fail to realize how self-defining work really is. This speaks to work''s centrality but also to its invisibility in reflective discourse. However, through “popular” representations of work (e.g., such as in story-telling, cave drawings, hieroglyphs, music, writing, painting, television, film, video games, etc.,) we can begin to better understand the meaning of work and how this has changed over time. Readings in anthropology, history, economics, sociology and employment relations plus film and art criticism will help us explore these questions from an interdisciplinary perspective; assignments will encourage students to reflect on their own experience of work. Developing strong analytical and communication skills is an important goal of the course. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('IRE242H1', 'HRM for Industrial Relations and HR Professionals', '12L/24P', 'This course explores the relationship between human resource management, employment relations, and industrial relations. Extensive practical course work will expose students to the functions human resource professionals execute to recruit, select, compensate, train, and evaluate the performance of employees. The course prepares students for advanced HR topics in upper level IRE courses. Note: Course will not count towards Rotman Commerce program requirements.', 'RSM361H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRE244H1', 'Labour Relations', '36L', 'Introduction to the institutions, issues and legislation affecting the employment relationship in the public and private sectors in Canada, with emphasis on collective bargaining. The economic and political environment, history of the labour movement, union organization, certification, contract negotiation, strikes, dispute resolution, contract administration and grievances.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRE260H1', 'Organizational Behaviour', '24L', 'Introduction to the nature of organizations and the behaviour of individuals and groups within organizations, including topics such as culture and diversity, reward systems, motivation, leadership, politics, communication, decision-making, conflict and group processes. Not recommended for students in Commerce programs.', 'PSY332H1,  RSM260H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRE299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IRE299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IRE332Y0', 'Topics in Industrial Relations and Human Resources (Summer Abroad Program)', null, 'Topics in Industrial Relations and Human Resources offered in an international setting. The content may vary from year to year. For more information check the Summer Abroad website.', null, 3, null::jsonb),
    ('IRE339H1', 'Labour Markets and Public Policy', '36L', 'This course is designed to provide students in the IRHR program with knowledge of how the labour market affects the employment relationship. The basic tools of labour economics are developed and applied to various issues of organizational and government policy such as: the incentive effects of compensation arrangements, government income support programs, and minimum wage policy; the determinants of preferences for hours of work including job-sharing, overtime and retirement; the impacts of unions on compensation and productivity; public-sector employment and alternatives to the right to strike; discrimination in employment on the basis of gender and race as well as related government policies such as pay and employment equity.Note:  IRE339H1 will not count towards an ECO program.', 'ECO339H1', 3, '{"operator": "OR", "items": ["ECO101H1", "ECO105Y1", "IRW230H1"]}'::jsonb),
    ('IRE342H1', 'Essentials of Finance and Accounting', '24L/12T', 'This course introduces students to accounting and finance procedures and concepts used by organizational leaders and professionals. The course covers both managerial and financial accounting topics with applications to organizational decision-making. Note: Course will not count towards Rotman Commerce program requirements.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["IRE242H1", "IRW240H1"]}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('IRE344H1', 'Topics in Industrial Relations and Human Resources', '36L', 'Topics vary from year to year, but the objective of the course is to discuss current IRHR issues and their economic, legal, political and social implications.', null, 3, '{"operator": "AND", "items": ["IRE242H1"]}'::jsonb),
    ('IRE345H1', 'Topics in Industrial Relations and Human Resources', '36L', 'Topics vary from year to year, but the objective of the course is to discuss current IRHR issues and their economic, legal, political and social implications.', null, 3, '{"operator": "AND", "items": ["IRE242H1"]}'::jsonb),
    ('IRE346H1', 'HR Planning & Strategy', '36L', 'An understanding is developed of how essential elements of the human resource planning process support organizational goals and strategies. Topics such as environmental influences, job analysis, forecasting human resource needs and ascertaining supply, succession planning, downsizing and restructuring, mergers and acquisitions, outsourcing, and strategic international issues are examined.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}]}'::jsonb),
    ('IRE347H1', 'Training & Development', '24L', 'The role of training and development initiatives in organizations. Students acquire the knowledge and skills to conduct a training needs assessment, identify training objectives, explore strategies to increase the transfer of training, design and deliver a training activity using various training methodologies, and evaluate its effectiveness.', null, 3, '{"operator": "AND", "items": ["IRE242H1"]}'::jsonb),
    ('IRE348H1', 'Recruitment & Selection', '24L', 'The principles, legal issues, and emerging trends affecting the recruitment process and selection of staff in organizations. Development of recruitment strategies, assessment of applications for employment, interviewing candidates, and the role of testing and measurement of competencies in making hiring decisions.', null, 3, '{"operator": "AND", "items": ["IRE242H1"]}'::jsonb),
    ('IRE367H1', 'Compensation', '24L', 'The theory and process of developing and administering compensation systems. Through the core compensation principles of efficiency, equity, consistency and competitiveness we consider such topics as: job analysis, job evaluation, pay levels and structures, pay for performance, benefits, and compensating special groups of workers.', null, 3, '{"operator": "AND", "items": ["IRE242H1"]}'::jsonb),
    ('IRE378H1', 'Employment Health', '36L', 'The influence of legislation, the labour market and collective bargaining on health policies and programs in the workplace. The rights and responsibilities of employers, employees, unions and governments for the regulation and promotion of workplace health and safety; and the implications of evolving demographic, economic, and social factors.', null, 3, '{"operator": "OR", "items": ["IRE244H1", "IRE260H1"]}'::jsonb),
    ('IRE379H1', 'Research and Data Analytics', '24L/12T', 'Data science is changing the way organizations make decisions and the way work is done. This course introduces basic data analytics concepts for understanding the measurement of performance, analysis of organizational policies, and effective communication and visualization of data. Students will develop basic data skills in the R statistical computing environment.', 'ECO220Y1', 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}]}'::jsonb),
    ('IRE395H1', 'Independent Study', null, 'Independent study under the direction of a faculty member. Open only when a faculty member is willing and available to supervise. Application form is due one week before the start of term. Consult the program website for additional information. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": ["IRE244H1", "IRE260H1"]}'::jsonb),
    ('IRE396H1', 'Research Participation', null, 'Credit course for supervised participation in a faculty research project. Offered only when a faculty member is willing and available to supervise. Consult the program website for additional information. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": ["IRE244H1", "IRE260H1"]}'::jsonb),
    ('IRE399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IRE399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('IRE430H1', 'Canadian Employment Law & the Non-Union Workplace', '24L', 'The course will focus on the law governing employment in a non-unionized workplace. Specifically, it will cover every phase of the employment relationship from hiring to termination and beyond and the rights and obligations of employers and employees as developed by the Courts and under employment-related statutes (namely the Employment Standards Act, 2000 and the Human Rights Code.) The course will also cover provisions from the Occupational Health and Safety Act.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('IRE431H1', 'Canadian Labour Law & the Unionized Workplace', '24L', 'The course will focus on the laws impacting unionized workplaces. It will cover every phase of the Ontario Labour Relations Act, 1995 (the “LRA”) from union organizing, certification, negotiation and bargaining, collective agreement arbitration, retention of bargaining rights and decertification and termination of bargaining rights.', null, 3, '{"operator": "AND", "items": ["IRE430H1"]}'::jsonb),
    ('IRE432Y0', 'Advanced Topics in Industrial Relations and Human Resources (Abroad)', null, 'Advanced topics in Industrial Relations and Human Resources offered in an international setting. The content may vary from year to year. Offered by the Professional & International Programs Office.', null, 3, '{"operator": "AND", "items": [{"credits": 13.0, "department": null}, "IRE244H1", "IRE260H1", {"credits": 1.0, "department": "IRE"}]}'::jsonb),
    ('IRE444H1', 'Seminar in Industrial Relations and Human Resources', '24S', 'An advanced seminar examining contemporary issues in the IRHR field. Topics vary from year to year, but the objective of the course is to discuss current issues and their economic, legal and social implications.', null, 3, '{"operator": "AND", "items": ["IRE244H1", "IRE260H1", {"credits": 1.0, "department": "IRE"}]}'::jsonb),
    ('IRE446H1', 'Working as an Internal Organizational Consultant', '24S', 'This course examines the various elements of the consulting process and the interpersonal skills required to build trust, influence others, contract with clients, and establish and maintain strong working relationships. This seminar may include a compulsory learning format component using a service-learning placement with a community-based agency or organization.', 'IRW446Y1', 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": "IRE"}]}'::jsonb),
    ('IRE447H1', 'Contemporary Challenges Facing Today''s Organizations', '24S', 'An advanced seminar exploring significant developments in organizations, and the challenges and opportunities facing professionals in the employment relations field. Emphasis is placed on developing problem solving and critical thinking skills and examining theories and concepts of employment relations.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": "IRE"}]}'::jsonb),
    ('IRE472H1', 'Negotiations', '24S', 'Resolving conflicts constructively is a challenge faced by all organizations and most individuals. This course will cover fundamentals of the negotiation process and conflict resolution. This course will apply multiple cases and simulations providing students with several opportunities to build their skills.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('IRE494H1', 'Advanced Topics in Industrial Relations and Human Resources', '24S', 'Advanced topics vary from year to year, but the objective of the course is to explore theories, concepts and emerging issues in IRHR and their impact on internal and external environments.', null, 3, '{"operator": "AND", "items": ["IRE244H1", "IRE260H1", {"credits": 1.0, "department": "IRE"}]}'::jsonb),
    ('IRW220H1', 'Statistics for Work and Organizations', '24L', 'This course covers the fundamentals of statistical data analysis including the principles of data visualization, descriptive statistics, sampling distribution, hypothesis testing, and regression analysis using free statistical software (R/R Studio). The emphasis is on fostering a conceptual understanding of different statistical techniques and analysis applicable to the workplace and within organizations.', 'ECO220Y1/  EEB225H1/  GGR270H1/  POL222H1/  PSY201H1/  SOC202H1/  STA220H1/  STA238H1/  STA248H1/  STA288H1/  MGEB12H3/  PSYB07H3/  STAB22H3/  STAB23H3/  ECO227Y5/  PSY201H5/  STA215H5/  STA218H5/  STA220H5', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRW230H1', 'Economics of Work and Organizations', '24L', 'The foundations of economic thinking as well as an introduction to economic theories that explain why organizations exist, the central economic theories of work and worker behaviour; the incentives that make workers and firms behave optimally and an introduction to the new behavioural economic theories of work and organizations are all part of this course. Note: Course will not count towards Economics program requirements.', 'ECO101H1/  ECO105Y1/  ECO101H5/  MGEA01H3/  MGEA02H3', 3, null::jsonb),
    ('IRW240H1', 'Introduction to Work and Organizations', '24L', 'The study of work and the history and development of organizations, their central theories and concepts; the behaviours, outcomes, practices and institutions that emerge from or affect work and organizations; contemporary issues in work and organizations.', 'IRE240H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRW300H1', 'Effective Communication and Strategic Writing in Organizations', '24L', 'This course is focused on understanding and crafting strategic, effective, and ethical written and verbal communications in organizations. We will learn scholarly approaches from the social sciences and humanities regarding organizational communications and miscommunications, including those directed internally and externally from complex organizations.', 'WRR300H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('IRW410H1', 'Organizational Governance and Design', '24L', 'Governance and design refers to “who gets to decide what and how” in organizations. This course examines the development of different types of organizations and governance arrangements, and different design archetypes within organizations. Focus is placed on how different governance and design arrangements support different strategic objectives and goals and ways of coordinating work effort.', null, 3, '{"operator": "AND", "items": ["IRE260H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('IRW420H1', 'Management Skills for Project and Strategy Implementation', '36L', 'The course focuses on understanding the challenges, constraints, and opportunities associated with formulating and implementing organizational strategy, with a focus on developing practical tools and skills required to effectively “get things done” in organizations. Course begins by giving students a framework to analyze organizations from strategic, political and cultural lenses. Subsequently, the course addresses three main issues central to “getting things done” in organizations: 1. how to gain influence in organizations (topics: decision-making, power, and networks), 2. how to manage others (topics: performance management, motivation, negotiations), and 3. how to drive organization change (topics: organizational culture, organizational change).', null, 3, '{"operator": "AND", "items": ["IRE260H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('IRW432Y1', 'Entrepreneurship', '24L/24P', 'Students will learn about the theory and practice of entrepreneurship as well as determinants of entrepreneurial success by developing a business or organizational plan to bring their “proposed” product and service ideas to market, to achieve a local community or social development objective, to learn how to secure funding for a new venture creation through individual and/or collective entrepreneurship.', 'RSM493H1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('IRW446Y1', 'Working as an Organizational Consultant', '24L/24P', 'In this capstone course, students will learn about the growth and development of consulting and its intellectual foundations. After this background, consulting models and approaches will be explored and applied to real world problems. Students will work in groups on an actual organizational challenge. This challenge will either be internal to an organization or will involve external market research.', 'IRE446H1', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('IRW452Y1', 'Capstone Research Project', '24L/24P', 'In this capstone course, students will have the opportunity to design and implement an original research project on work and organizations. Students will receive in-class training and guidance on: 1) developing and refining a research question, 2) identifying and implementing appropriate research methods, 3) locating or collecting relevant data, 4) identifying the significance of their work to various audiences, and 5) effectively writing a research paper. Not eligible for CR/NCR option.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 1.0, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('ITA100Y1', 'Italian Language for Beginners', '72S', 'An introduction to the main elements of the Italian language. The development of speaking, reading, and writing skills. Introduction to Italian culture and texts.  A questionnaire on students'' knowledge of and background in Italian will be administered shortly before or during the first class.', 'Grade 11 and/or 12 Italian (U or M level) or previous experience or instruction in Italian.', 1, null::jsonb),
    ('ITA102Y0', 'Practical Italian', '48L/24P', 'A course specifically designed for students who wish to take Italian as a breadth requirement. Emphasis will be given to basic aspects of communication in a functional context. This course cannot be used towards any Minor, Major or Specialist program in Italian. (Offered in Siena only)', '4U Italian or any previous university level Italian language course', 1, null::jsonb),
    ('ITA196H1', 'Image and Text in Medieval and Renaissance Italian Culture', '24L', 'The course will explore various aspect of the interaction between literature and the visual arts in Italy from the Middle Ages to the end of the Renaissance. The focus will be on the intersection between the literary and visual modes of perception in the works of representative Italian authors from the Fourteenth to the Sixteenth Centuries. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('ITA197H1', 'The Fine Art of Murder: Reading Detective Fiction', '24L', 'Since its inception in the Nineteenth century, detective fiction has been one of the most popular literary genres, proving adept at both entertaining and shining a critical light on social and political problems. This course will explore the many faces of detective fiction addressing questions such as: Why does crime hold such a fascination for modern audiences? What kind of pleasure do we derive from reading stories that often follow established conventions and rules? What do these novels about crime and punishment tell us about broader social and political issues? Restricted to first-year students. Not eligible for CR/NCR option.', 'VIC197H1', 1, null::jsonb),
    ('ITA198H1', 'Machiavelli and Machiavellianism', '24L', 'An examination of Machiavelli''s political doctrine in The Prince and the development of his ideas in politics, ethics and the arts. Special attention will be paid to the enduring relevance of his legacy in the modern world. Restricted to first-year students. Not eligible for CR/NCR option.', 'VIC142H1', 1, null::jsonb),
    ('ITA199H1', 'Italian Fascism and Global Responses: The Dark Side of Italianità', '24L', 'After WWI, Italian society faced a political, economic, and moral crisis that resulted in the rise of fascism. Using diverse sources (media, literary texts, movies, architecture and design), this course explores various reactions in Italy and abroad to the rise of Mussolini and the totalitarian State. Why did common people, intellectuals, politicians, and business and community leaders around the globe succumb to the seduction of fascism? How did other people denounce fascist violence? After an introduction to Italian fascism, the course will consider global reactions to Italian fascism and diverse responses in Italian communities abroad (e.g. Canada, USA, Argentina). Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('ITA200H1', 'Major Italian Authors in Translation: from Dante to Tasso', '24L', 'The course will focus on authors from the Middle Ages to the Renaissance who had a defining influence on Western literature, such as Dante, Petrarca, Boccaccio, Machiavelli, Ariosto and Tasso. This course includes a component designed to enhance students'' research experience. (Given in English)', 'ITA300H1', 1, null::jsonb),
    ('ITA201H1', 'Major Italian Authors in Translation: from Marino to Calvino', '24L', 'The course will focus on authors from the Baroque to the Twentieth Century who had a defining influence on Western literature, such as Marino, Goldoni, Manzoni, Pirandello, Calvino. This course includes a component designed to enhance students'' research experience. (Given in English)', 'ITA301H1', 1, null::jsonb),
    ('ITA210H1', '“The Most Beautiful Language”: Italian between Past, Present and Future Challenges', '24L', 'In his recent book, titled “The most beautiful language” (La più bella del mondo, Turin: Einaudi, 2018), Stefano Jossa eulogizes Italian, arguing that it should be learned by many. However, what do we really know about it? The course will try to answer some crucial questions: How was the Italian language born and developed? What are its main characteristics? How are the many dialects perceived in Italy today? What status do they have vis-à-vis the national language? What about the expansion of English? Are the dialects disappearing or still surviving? How is Italian language facing the new social questions (gender, diversity, etc.)? How are social media changing the way the Italian language is written and spoken?', null, 2, null::jsonb),
    ('ITA233H1', 'Italian-Canadian Literature', '24L', 'The course will explore how notions of identity and (self)-representation emerge in literature by Canadian writers of Italian descent, illustrating the critical evolution of the immigrant journey from its historical experience to its current condition. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 3, null::jsonb),
    ('ITA240Y1', 'History of Italian Cinema', '48L/72P', 'This course surveys the history of Italian cinema and the sociopolitical circumstances surrounding the film industry, from its early days to the present, while also introducing the students to methods of analysis and research appropriate to the field. Emphasis will be placed on films from the silent era to the 1960s, and from the 1960s to the present. This course includes a component designed to introduce students to methods of scholarly research appropriate to the field. The course is given in English and all films shown have English subtitles.', null, 1, null::jsonb),
    ('ITA250Y1', 'Intermediate Italian', '72S', 'Grammar review, readings of Italian authors and oral practice to enhance comprehension and expressive skills. Students without the prerequisite will be asked to fill out a questionnaire on their knowledge of and background in Italian.', 'ITA251Y1', 1, '{"operator": "OR", "items": ["ITA100Y1", "ITA151Y1"]}'::jsonb),
    ('ITA299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA300H1', 'History of Italian Literature: Middle Ages and Renaissance', '24L', 'This course provides a chronological, comprehensive view of Italian literature and its major authors and trends, in their socio-historical contexts from its beginnings to the Renaissance. This course includes a component designed to enhance students'' research experience.', 'ITA200H1', 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA301H1', 'History of Italian Literature: Baroque to Contemporary', '24L', 'This course provides a chronological, comprehensive view of Italian literature and its major authors and trends, in their socio-historical contexts from the Baroque period to the present day. This course includes a component designed to enhance students'' research experience.', 'ITA201H1', 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA310H1', 'The ''Journey'' in 19th Century Italian Literature', '24L', 'The course illustrates Italy''s contribution to the history of the trope during a time when countries became increasingly interdependent and conscious of each other''s cultures. Through literary and social analysis the course traces the most vital aspects of the journey motif. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA311H1', 'Mediaeval Italian Literature in Translation: Dante', '24L', 'A study of the Vita Nuova and of the Divine Comedy within the literary and cultural contexts of the Middle Ages. This course includes a component designed to enhance students'' research experience. (Given in English)', 'ITA320H1/ ITA321H1', 1, null::jsonb),
    ('ITA312H1', 'Mediaeval Italian Literature in Translation: Petrarch and Boccaccio', '24L', 'A study of Petrarch''s Canzoniere and of Boccaccio''s Decameron in relation to later Middle Ages. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA314H1', 'Italian Design: Fashion, Artistry, Genius', '24S', '“Made in Italy” is a global standard for creativity and excellence in fashion, architecture, and industrial design. This course will explore how art, imagination, and craft have intersected in different areas of Italian culture over time. Based on an individual instructor’s area of expertise, themes explored may include studies of the Italian fashion industry, food culture, commercial art, and industrial design. Primary materials will include artworks, literary texts, material objects, and mixed media that demonstrate the importance of design culture in Italy and the impact of Italian design culture in the world. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ITA315H1', 'Sex and Gender in Contemporary Italy', '24S', 'This course will focus on theoretical and cultural productions that deal with issues of sexuality and gender in (contemporary) Italy. Based on an individual instructor’s area of expertise, themes explored may include feminism and women’s rights, sexual liberation and LGBTQ+ rights, Queer-of-Colour critique, and other topics within the study of sexual and gender diversity. Primary materials will include manifestos, theoretical essays, novels, short stories, and films that deal with gender and sexual diversity in the Italian-speaking world and from a transnational perspective. Linguistic issues will also be discussed. This course includes a component designed to enhance students'' research experience.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ITA320H1', 'Dante: Vita Nuova and Divina Commedia (Inferno)', '24L', 'Dante’s poetry and great Christian epic of conversion explode with the passions of this world. This course focuses on intertextual and rhetorical strategies used to fashion the author’s complex vision of contemporary society within the framework of providential history. This course includes a component designed to enhance students'' research experience.', 'ITA311H1', 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA321H1', 'Dante: Divina Commedia (Purgatorio and Paradiso)', '24L', 'A continuation of  ITA320H1, this course examines the Purgatorio and the Paradiso in the context of Dante’s vision of contemporary society. This course includes a component designed to enhance students'' research experience.', 'ITA311H1', 1, '{"operator": "AND", "items": ["ITA320H1"]}'::jsonb),
    ('ITA332H1', 'Love in the Renaissance', '24L', 'An exploration of the theme of love in the Renaissance and its development in a variety of literary forms. Analysis of treatises, poetry, short stories and letters with the purpose of examining intertextuality and the practice of imitation, as well as the social and political aspects of love, such as marriage, women’s position in society, pornography, homosexuality and other issues. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA333H1', 'Identity Politics in Renaissance Italy', '24L', 'This course explores the intersection of religion, gender, and race in the literature and culture of Renaissance Italy. Between 1350 and 1650, constructs of identity based on these categorizations consolidated into cultural norms that influenced modern colonialism and contemporary nationalism. In this course, we will investigate how texts and ideas that we normally place at the core of the myth of the Italian Renaissance were always in dialogue with fantasies of power, exceptionalism, and orientalism. We will pair close reading of a wide range of literary genres (romance, dramaturgy, fiction, travelogues, political writing) with visual artifacts and archival materials. Authors to be studied include Boccaccio, Petrarch, and Ariosto.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ITA340H1', 'Italian Neorealist Cinema', '24L/36P', 'The focus of this course is the films of Italian Neorealism, one of the most influential, artistic, and intellectual movements in the history of world cinema. While emphasis will be placed primarily on the work of Roberto Rossellini, Vittorio De Sica, and Luchino Visconti, the course will also offer a detailed discussion of the historical context and of the sociopolitical issues of postwar Italy. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA341H1', 'Gender and Genre in Italian Cinema', '24L/36P', 'The course looks at Italian cinema from the perspective of gender and genre studies. While the focus will be primarily on film, the course will also engage with different media and discuss how these have informed and influenced Italian notions of masculinity and femininity throughout the Twentieth Century. The emphasis on genre will provide the structure to organize a discourse that will embrace very diverse and multifaceted texts, and will enable students to develop their analytical and critical skills in the field. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA342H1', 'Popular Italian Cinema', '24L', 'This course discusses the notion of the Popular as applied to Italian cinema. By focusing on the number of films that have appropriated popular international genres such as Spaghetti Westerns, Horror, and Poliziotteschi, this course will discuss Italian cinema in a global context, drawing parallels and comparisons with other national industries. Students will gain a broader understanding of Italian film culture, and will apply their critical and research skills to a wide range of texts. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA345H1', 'Cinema of the Italian Diasporas', '24L/36P', 'This course will examine how several filmmakers of Italian descent engage with the representation of their diasporic identity. Particular emphasis will be placed on Italian-Canadian and Italian-American cinema, as well as on Italian cineastes working in Argentina, Brazil, and Australia. The course will analyze films that span from silent to contemporary, from the formation of the stereotypical images to the re-appropriation of archetypes on the part of “ethnic” filmmakers. This course includes a component designed to enhance students'' research experience.(Given in English)', null, 1, null::jsonb),
    ('ITA348H1', 'Mass Media in Italy: The European Context', '24L', 'This course investigates Italy’s pivotal role in epochal cultural changes:  from manuscript to print and from print to computers.  The impacts of Print Technology in the Renaissance and of Electronic Technology from Marconi onward are thoroughly analyzed.  This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA349H1', 'Black Italian Cultural Production', '24L', 'This interdisciplinary course will explore the landscape of cultural production made by Italians of African descent. The course provides students with relevant historical and sociological background necessary to understand entanglements of race, gender, identity, and citizenship occurring in contemporary Italy. The analysis of cultural production includes literature, music, cinema, television, visual arts and fashion. Students read not only academic material but also short stories, novels and poems; listening to and analyzing rap, trap and hip-hop tracks; watching online exhibitions and documentaries; examining Netflix series and Instagram pages. When possible, the course will also host Italian artists and activists engaging in conversations about their work.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('ITA350Y1', 'Language Practice', '24P/48S', 'For students who have completed  ITA250Y1/ ITA251Y1. Discussion of problems of grammar, style, and composition. Language analysis based on readings of Italian authors. One hour a week of oral practice. This course includes a component designed to enhance students'' research experience. Students without the prerequisite(s) will be asked to fill out a questionnaire on their knowledge of and background in Italian.', 'ITA351Y1', 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA358Y0', 'Modern Italian Culture', '24L/24T', 'Analysis of a selection of philosophical, artistic, musical, and literary works from the age of the Baroque to the present. The main topics of discussion include: Romanticism, Italian unification, theatre, opera, Futurism, fascism, Neorealism, regional differences, and industrialization. Field trips and viewing of movies included. This course includes a component designed to enhance students'' research experience. (Offered in Siena only)  ITA358Y0: This course is taught in English and is open to students from other disciplines.', null, 3, null::jsonb),
    ('ITA359Y0', 'Modern Italian Culture', '24L/24T', 'Analysis of a selection of philosophical, artistic, musical, and literary works from the age of the Baroque to the present. The main topics of discussion include: Romanticism, Italian unification, theatre, opera, Futurism, fascism, Neorealism, regional differences, and industrialization. Field trips and viewing of movies included. This course includes a component designed to enhance students'' research experience. (Offered in Siena only)  ITA359Y0: Students who wish to petition the Department for credit towards a Specialist or Major in Italian will be required to do the readings in Italian.', null, 3, null::jsonb),
    ('ITA360H1', 'Italian Linguistics', '24L', 'For students having a knowledge of Italian and/or Italian dialects but no background in linguistics. Concepts of general linguistics. Italy as a linguistic entity. The structure of contemporary Italian, with special regard to its sound system and grammatical categories. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA363H1', 'Italian Sociolinguistics', '24L', 'Starting with a survey of the sociolinguistic situation in Italy before Unification, this course deals with the complex relationship between regional languages and dialects on the one hand and Common Italian on the other. The recent rise of regional variants of Italian and its impact on the dialects are also discussed. This course includes a component designed to enhance students'' research experience.', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA364H1', 'Italian and Social Media', '24L', 'The aim of this course is to examine how media can influence the evolution of language in contemporary Italy. The first part of this course has an historical goal and will be devoted to the role played by ‘traditional’ media (television, radio, newspapers) in the linguistic history of Italian. The second part will be devoted to the impact that social media is having on Italian. Empirical quantitative research will be based on the most important databases for contemporary Italian.', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA367H1', 'Topics in Italian Linguistics', '2L', 'An open course that explores specific aspects of Italian Linguistics. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA378H1', 'Topics in Italian Studies', '24L', 'An open course that explores specific aspects of Italian Studies. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA379H1', 'Topics in Italian Studies', '24L', 'An open course that explores specific aspects of Italian Studies. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1", "ITA252Y1"]}'::jsonb),
    ('ITA380H1', 'The Prose of the World: The Modern Italian Novel and the Realist Tradition', '24L', 'This course examines the development of modern Italian novel by taking as its focus the question of the relationship between narrative and the world. The course analyzes some of the major figures of Nineteenth-Century realist tradition such as Manzoni and Verga, as well as the resurgence of realist narrative in the post-World War II period with authors such as Pavese and Calvino. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA390H1', 'The Commedia dell''Arte', '24L', 'A study of the conventions of the Commedia dell''Arte tradition in the context of its performance history from the late Renaissance to the present. Issues examined include acting techniques, improvisation, masks and costumes, iconography and adaptation to film. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA395Y0', 'Special Topics in Italian Studies', '48S', 'The area of concentration will depend upon the instructor teaching the course in any given year. (Offered only during the summer through the Summer Abroad Program.) Not available for CR/NCR option.', null, 1, null::jsonb),
    ('ITA398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('ITA400H1', 'Machiavelli', '24S', 'An intensive study of Machiavelli’s major works in English translation, including his political treatises (The Prince, excerpts from The Discourses), plays (The Mandrake Root), letters, and short story (Belfagor), in the context of Renaissance Florence, the history of Machiavelli criticism, and modern ethical debates. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 2, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('ITA410H1', 'Masterpieces of Modern Drama', '24L', 'This course will study works by the major Italian playwrights of the Twentieth Century, including two of Italy’s Literature Nobel Prize winners, Luigi Pirandello and Dario Fo. Particular attention will be paid to the relationship between individual works and broader literary and cultural movements, as well as to issues regarding staging and production of the plays under discussion. The course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}, {"credits": 0.5, "department": "ITA"}]}'::jsonb),
    ('ITA420H1', 'Spinning a Tale: The Italian Short Story from Boccaccio to Basile', '24L', 'The short story genre and its development from the Middle Ages to the Baroque. In addition to Boccaccio’s tales, included are some of the most famous stories of Western literature, which later inspired masterpieces in all art forms, such as Romeo and Juliet, Othello and Puss in Boots. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}, {"credits": 0.5, "department": "ITA"}]}'::jsonb),
    ('ITA421H1', 'Spinning a Tale: The Italian Short Story after 1800', '24L', 'Focusing on short stories by some of the most important authors of the Twentieth Century, such as Pirandello and Calvino, this course will provide an introduction to the major tendencies of contemporary Italian literature. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}, {"credits": 0.5, "department": "ITA"}]}'::jsonb),
    ('ITA425H1', 'Special Topics in Italian Studies', '24L', 'A course on specific topics in Italian Studies, designed for advanced students. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, '{"operator": "AND", "items": [{"credits": 7.0, "department": null}]}'::jsonb),
    ('ITA426H1', 'Special Topics in Italian Studies', '24L', 'A course on specific topics in Italian Studies, designed for advanced students. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA427H1', 'Special Topics in Italian Linguistics', '24L', 'A course on specific topics in Italian Linguistics, designed for advanced students. This course includes a component designed to enhance students'' research experience.', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA431H1', 'History of Italian Language I-from Middle ages to Cinquecento', '24L', 'An historical overview of the Italian language from the first Medieval documents to the texts of the Questione della Lingua. It deals with historical grammar and the analyses of early Italian texts. An introduction to notions of linguistic statistics. Empirical quantitative methods are based on the three most important databases of old Italian: TLIO,OVI,BIZ. This course includes a component designed to enhance students'' research experience.', 'ITA430H1', 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA432H1', 'History of Italian Language II- from Cinquecento to Contemporary', '24L', 'The evolution of the Italian Language from the Questione della lingua to Contemporary issues pertaining to reading of literary and non-literary documents and analyses of the social, political and economic conditions which influenced Early Modern, Modern and Contemporary Italian. Introduction to techniques pertaining to notions of linguistic statistics. Quantitative methods will be based on the three most important databases for the Early modern, Modern and Contemporary Italian: Vocabolario della Crusca (online), BaDIP and BIZ. This course includes a component designed to enhance students'' research experience.', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA433H1', 'Italian Language and Italian Dialects in Toronto', '24L', 'Through an historical overview of Italian immigration in Toronto, the role of Italian and Italian dialects in the city will be examined. As part of the topic studied in course, students will contribute to the website of the OIM by collecting varied forms of empirical linguistic evidence.', null, 2, '{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}'::jsonb),
    ('ITA441H1', 'Italian Cinematic Adaptation', '24L', 'An analysis of the process of adaptation in an exploration of the ideological and narratological perspectives as well as the stylistic elements of literary and cinematic discourse. Selections include novels by Verga, Tomasi di Lampedusa, Moravia, Bassani and their filmic adaptations by directors such as Visconti, De Sica, Bertolucci. This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA445H1', 'Literature of the Italian Diasporas', '24L', 'This course examines works by writers of Italian descent, focusing on themes linked to the second-generation experience, such as intergenerational conflict, gender relations, the return journey, and the quest for identity. The comparative approach of this investigation will bring within the same framework the diasporic literatures of Canada, the United States, Argentina, Brazil, Australia, and of other countries. (Texts available in English and in their original language). This course includes a component designed to enhance students'' research experience. (Given in English)', null, 1, null::jsonb),
    ('ITA450H1', 'Advanced Italian', '36S', 'This advanced-level course is designed to provide students with further study of the Italian language and culture with emphasis on varied methods of expression. This course will improve students'' oral and written communication skills.', 'ITA451H1/ ITA452H1', 1, '{"operator": "OR", "items": ["ITA350Y1", "ITA351Y1"]}'::jsonb),
    ('ITA453H1', 'At the Movies: History and Practice of Italian Film Criticism', '24S', 'This course will provide students with a blend of history, methodology, and practice of Italian film criticism. The first module will survey the primary trends and methodological developments in the long history of Italian film criticism, from the days of silent cinema to the most recent changes caused by online platforming. The second module will offer students the opportunity to write their own criticism, and to collaborate with Italian online film magazines. Given in Italian.', null, 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}, "ITA350Y1", "ITA351Y1"]}'::jsonb),
    ('ITA455H1', 'Women Writers in Italy', '24L', 'The course will focus on the writings of women in different periods of Italian history. Spanning a variety of genres, from the novel to autobiography, from poetry to essayism, the course will discuss various aspects of the debate regarding the changing roles of women in society. This course includes a component designed to enhance students'' research experience.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["ITA250Y1", "ITA251Y1"]}, {"credits": 0.5, "department": "ITA"}]}'::jsonb),
    ('ITA460Y1', 'Internship in Italian', '48P', 'Opportunity to apply acquired knowledge in a work placement environment. The placement will take place in local community organizations, Private Business Associations and local media.', null, null, '{"operator": "OR", "items": ["ITA350Y1", "ITA351Y1", "ITA352Y1", "ITA371Y1"]}'::jsonb),
    ('ITA489H1', 'Independent Studies', null, 'An opportunity to pursue at the 400-level an independent course of study not otherwise available. A written proposal, co-signed by the instructor, must be submitted on the appropriate proposal form for approval by the Department of Italian Studies. Application deadline: April 30 for F courses, November 30 for S courses.', null, null, null::jsonb),
    ('ITA490Y1', 'Independent Studies', null, 'In exceptional circumstances, students may request to pursue at the 400-level an independent course of study not otherwise available. A written proposal, co-signed by the instructor, must be submitted on the appropriate proposal form for approval by the Department of Italian Studies. Application deadline April 30.', null, null, null::jsonb),
    ('ITA495H1', 'Directed Research', null, 'Based on a professor''s research project currently in progress, this course will enable an undergraduate student to play a useful role in the project while receiving concrete training in research. This course is mandatory for all students enrolled in the specialist''s program.', null, null, null::jsonb),
    ('ITA496H1', 'Research Methods', null, 'This course, linked to the instructor''s research project, will provide training in a variety of research methods. This course includes a component designed to enhance students'' research experience.', null, null, null::jsonb),
    ('JAA377H1', 'Black Radical Theory from the Global South: Anthropological Perspectives', '24L', 'This course will survey the works of Black theorists and anthropologists from the Global South, who are shaping current debates within and beyond the discipline of Anthropology, concerning colonialism and decolonization, Marxism, indigeneity, political economy, Black radical thought, queer theory and decolonial feminism. Students will look at how these works challenge the “Northern Academy’s monoliteracy” (Musila), politics of knowledge production and construction of the Global South as primarily a site of fieldwork and research extraction. Authors will include Sylvia Tamale, Wangui Kimari, Sabelo Ndlovu-Matsheni, Ochy Curiel, Keguro Macharia, Beatriz Nascimento, Michel-Rolph Trouillot and Abdelghaffar Ahmed.', null, 3, '{"operator": "OR", "items": ["ANT204H1", "ANT207H1", "ANT215H1", "AFR150Y1", "AFR290H1", "AFR298H1"]}'::jsonb),
    ('JAH350H1', 'AIDS, Outbreaks, Pandemics: Challenges and Successes in Africa', '24L', 'Explores a range of historical and current outbreaks, pandemics and epidemics such as AIDS, COVID-19 and Ebola in Africa through a social science lens. It introduces students to major concepts, events and debates that have and continue to shape understanding of the HIV/AIDS epidemic, Ebola outbreak and COVID-19 pandemic, and the challenges and responses to these distinct health crises. Through a critical lens, students will engage diverse and interdisciplinary scholarship from public health, medical anthropology, sociology, African studies, and related fields within the health and social sciences fields to explore the converging factors that influence responses to health crises and their broader implications.', 'JNH350H1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('JAL328H1', 'Writing Systems', '36L', 'Introduction to writing systems; their historical development, their relationship to language, and their role in culture and society. (Given by the Departments of Anthropology and Linguistics) (Not offered every year)', null, 2, '{"operator": "OR", "items": ["ANT100Y1", "LIN101H1", "LIN200H1"]}'::jsonb),
    ('JAL355H1', 'Language and Gender', '24L', 'An introduction to some of the principal questions of feminist theory, as viewed from sociolinguistics. Topics include: socialization into gendered discourse patterns, cultural and ethnic differences in gendered interactions; the role of language and gender in legal, medical and labour settings; multilingualism, migration, imperialism and nationalism; sexuality, desire and queer linguistics, language, gender and globalization.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('JAL401H1', 'Field Linguistics', '48P', 'Field Linguistics provides practice in language analysis based on elicited data from a native speaker of an indigenous or foreign language, emphasizing procedures and techniques. (Given by the Departments of Anthropology and Linguistics)', 'LIND46H3', 2, '{"operator": "AND", "items": ["LIN322H1", "LIN331H1"]}'::jsonb),
    ('JAV120H1', 'Visual Concepts', '12L/36P', 'An introduction to a wide range of topics situated in modernism, postmodernism, and the contemporary that inform current art practice and critical discourse. The course investigates post-1970 art practice through diverse societal, cultural, and political influences of contemporary critical thought.', 'VIS120H1', 3, null::jsonb),
    ('JAV130H1', 'Visual Strategies', '24L/12T', 'An introduction to diverse mediums and topics for exploration with an emphasis on experimentation and conceptual development. In addition to acquiring manual skills used in production of contemporary visual art, students are encouraged to explore their own individual artistic and research processes.', 'VIS130H1', 1, '{"operator": "OR", "items": ["JAV120H1", "VIS120H1"]}'::jsonb),
    ('JAV200H1', 'Introduction to Critical Theory', '24L/12T', 'A course that teaches critical and analytical ways of engaging visual culture within an interdisciplinary and international setting. Students are introduced to foundational intellectual tools and a research methodology appropriate to artists, designers, and architects.', 'VIS200H1', 2, null::jsonb),
    ('JCA302H1', 'The Bible and the Big Bang', '24L/12T', 'The origin of the Universe is addressed both by current physical cosmology and by religious interpretations of the Bible. This course explores how these approaches to the cosmos''s origins differ and how they might be mutually informative. Core concepts in each domain will be examined and definitions carefully distinguished (e.g., ''nothing'', ''cause'', ''matter''): topics will include the question of temporal beginnings (scientific theories of spontaneous creation or an eternal universe vis-à-vis the doctrine of creation from nothing) and the problem of cosmic fine tuning (the multiverse vis-à-vis the idea of divine intervention).', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JCC250H1', 'Computing for Science', '24L/24T', 'Computational skills for the modern practice of basic and applied science. Applied computer programming with an emphasis on practical examples related to the simulation of matter, drawing from scientific disciplines including chemistry, biology, materials science, and physics. Studio format with a mixture of lecture, guided programming, and open scientific problem solving. Students will be exposed to Python numerical and data analysis libraries. No prior programming experience is required.', 'Any CSC course except  CSC104H1,  CSC196H1,  CSC197H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM135H1", "CHM136H1", "CHM151Y1"]}, {"credits": 0.5, "department": "MAT"}]}'::jsonb),
    ('JCI199H1', 'Italians in Canada: Histories, Journeys, Struggles, Successes', '24L', 'This course explores the presence of people from the Italian peninsula in what is now known as Canada. The course begins with discussions on Giovanni Caboto''s and other explorers'' journeys to then focus on contemporary Italian-Canadian communities. This course provides students with the critical tools necessary to understand various historical, linguistic, culinary, spiritual, political, and creative elements of Italian-Canadian identity and life. Students of both Italian and non-Italian heritage are most welcome in this course, which is taught in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('JCI250H1', 'Italian Canadian Communities', '24S', 'This course examines the past and present settlement patterns of those of Italian descent in Canada, in rural areas and cities, including increasing suburbanization. Students will address issues such as work and employment and political participation. Challenges and opportunities will be examined, with respect to issues such as migration, community-building, belonging, and discrimination.', null, 3, null::jsonb),
    ('JCI350H1', 'Italian Canadian Culture and Identity', '24S', 'This course examines the contributions of Canadians of Italian descent to arts, culture, identity and heritage in Canada, with attention to the diversity of the community with respect to issues such as language, religion, gender, class, sexuality, etc. A core concept addressed by the course is immigration, whether from the experiences of migrants themselves or later generations.', null, 3, null::jsonb),
    ('JCR303H1', 'Global Christianities', '24L/12T', 'An advanced introduction to the diverse traditions and movements of contemporary Christianity, with special emphasis on the global South. Sample topics include new ecclesial communities, the rise of Pentecostalism and independent churches, liberation and indigenized theologies, and new forms of martyrdom in the 21st century.', 'CHC303H1,  SMC204H1,  SMC207H1,  SMC209H1,  SMC303H1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JEG100H1', 'Introduction to Physical Geography and Earth Science', '24L/12P', 'This introduction to Physical Geography and Earth Sciences examines the atmosphere, lithosphere, hydrosphere, cryosphere and biosphere, emphasizing processes, flows of energy and materials, and the interconnectedness of these Earth systems. Specific topics include weather and climate, earth materials, geological and geomorphic processes involved in the genesis of landforms, river systems, glaciers, soils, and biomes.', 'GGR100H1,  ESS102H1,  EESA06H3', 5, null::jsonb),
    ('JEG201H1', 'Geomorphology', '24L/8P', 'This course introduces the principles of geomorphology, including the landforms and processes associated with water, wind, waves, and ice, as well as the human impacts on earth surface processes. Laboratory sessions occur irregularly during the semester to introduce assignments and provide support. A local field trip may be offered (transportation and entrance cost: approximately $26).', 'GGR201H1,  GGR201H5', 5, null::jsonb),
    ('JEG205H1', 'Introduction to Soil Science', '24L/4P', 'This course introduces the fundamentals of soil science, including the chemical, physical, and biological properties of soils as well as soil formation and development, the classification of soils, and the applications of soil science. A field trip may be offered (transportation cost: approximately $26).', 'GGR205H1', 5, null::jsonb),
    ('JEG206H1', 'Introduction to Hydrology', '30L/4P', 'Introduction to the hydrologic cycle with emphasis on the physical processes, including precipitation, interception, evaporation, runoff, ground water and soil water. Basic hydrological models will be practiced. Potential field trip, cost: approximately $21.', 'GGR206H1', 5, null::jsonb),
    ('JEG301H1', 'Fluvial Geomorphology', '24L/4P', 'Elements of drainage basin morphology and hydrology, classification of rivers, stream patterns and hydraulic geometry. Elements of open channel flow, sediment transport and the paleohydrology of river systems. River channel adjustments to environmental change, human impact and the management/design of river habitats. Exercises include experimentation in a laboratory flume. A field trip may be offered (at no cost). Course usually offered every other year.', 'GGR301H1', 5, '{"operator": "OR", "items": ["GGR201H1", "JEG201H1"]}'::jsonb),
    ('JEG305H1', 'Biogeography', '24L', 'Biogeography aims to identify and explain patterns of plant and animal distributions through space and time. This course considers topics including ecological and evolutionary dynamics, dispersal, migration, plate tectonics, speciation, extinction, paleoenvironments, and island biogeography. We will examine terrestrial and marine biomes, the meaning of biodiversity, conservation challenges, and recent biogeographic changes associated with human activities.', 'GGR305H1,  GGR305H5', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('JEG308H1', 'Canadian Arctic Environments', '24L', 'This course explores the unique physical geography of Canada''s Arctic regions by covering topics on climate, the cryosphere, hydrology, geomorphology, and ecosystems. Throughout the course, we will consider the impacts of climate change in communities, landscapes, and ecosystems in Arctic regions.', 'GGR308H1', 5, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('JEG406H1', 'Geomorphology and the Anthropocene', '12L/12S', 'In this seminar course, we will use lectures, readings, and classroom activities to investigate the ways in which Earth''s surface has been impacted by humans while considering the role of geomorphology as a science for understanding these changes.', 'GGR406H1', 5, '{"operator": "OR", "items": ["GGR201H1", "JEG201H1"]}'::jsonb),
    ('JEH455H1', 'Current Issues in Environment and Health', '16L/8S', 'This course introduces students to complex issues at the interface between environment and health where health is broadly defined. Each year a current and controversial case study is explored from scientific, medical, political and policy perspectives. The course takes students from the molecular to individual to population and societal levels.', null, 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["ENV341H1", "HMB302H1", "HMB312H1", "HMB314H1", "HMB322H1"]}]}'::jsonb),
    ('JFL388H1', 'Bilingualism, Multilingualism, and Second Language Acquisition', '24L/12T', 'Using and encountering multiple languages is the everyday norm of people living in much of the world, including in multicultural cities like Toronto. This course offers a broad exploration of the cognitive and social underpinnings of the dynamic field of bilingualism, multilingualism, and second language acquisition. We will (i) explore the differences between bilinguals/multilinguals and monolinguals in the ways they process and use language; (ii) examine the language acquisition patterns of children and adults; (iii) investigate the interactions between an individual''s language repertoires and those of their peers and local community.', 'FRE388H1,  JFG388H1', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JFL484H1', 'Computational Tools for Language Corpora', '24L/12T', 'This is a practical course dealing with digital collections of written language or transcribed oral language (corpora). It will introduce both the practical steps involved in building digital text corpora (text normalization, digitizing, tag set construction, and so on), as well as provide an understanding of, and hands-on experience with, fundamental techniques from computational linguistics and natural language processing, including techniques using machine learning, such as part-of-speech tagging, language models, and vector semantics. By working with real corpora, students will use these techniques to construct and defend hypotheses about texts, about languages, and about human language in general. An emphasis will be placed on using French language corpora from several periods (including medieval and modern) to situate French historically and in the Canadian context. Students will be given opportunities to work with other languages. Lectures will be in English, and students will take tutorials either in English or in French. Priority enrolment for students in major or specialist programs in Linguistics, French, or the Applied Data Science minor', 'LIN340H5.', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE272H1", "SPA322H1", {"operator": "AND", "items": ["LIN101H1", "LIN102H1"]}, "LIN200H1"]}, {"operator": "OR", "items": ["ENG286H1", "CSC108H1", "LIN240H5"]}]}'::jsonb),
    ('JFP450H1', 'Indigenous Issues in Health and Healing', '24L', 'The basic premise of this course is that the health of Indigenous peoples is inseparable from the health of the planet. The aim of the course is to facilitate collective healing from our current social and economic system in a process of awareness-based learning of our relationship to each other, the planet and ourselves. Starting with students'' reflection of their relationship to colonialism and traditional teachings, the course is built around a collaborative, interdisciplinary team project of selecting a domain of mutual interest, researching the existing decolonizing programs in the community within that domain, and developing an ethical, real-world prototype of action that they would want to continue to develop after the course is completed.', null, 3, null::jsonb),
    ('JGA305H1', 'Environmental and Archaeological Geophysics', '24L/12P', 'Application of near-surface geophysical methods to investigate environmental and archaeological sites; in particular magnetometry, resistivity, ground-probing radar, and seismic surveys. Course will cover background on the various methods, and allow students to run field surveys and present on case studies.', null, 5, '{"operator": "OR", "items": ["ESS241H1", "ESS262H1", "ANT200Y1", "ARH100Y1", "GGR201H1", "PHY224H1", "PHY250H1", "PHY254H1"]}'::jsonb),
    ('JGC439H1', 'The Problem and Promise of Caribbean Freedom', '24L', 'This course surveys the institutional and ideological structures that have historically internally and externally governed the Caribbean; the patterns of uneven development and crisis they have produced and the forms of agency, resistance they have produced. Centering the social, economic, and spatial inter-connectedness of the Caribbean territorial region and its increasingly de-territorialized diaspora, we explore possibilities for economic, social and climate justice for all Caribbean communities.', 'GGR400H1 (Special Topic: The Problem and Promise of Caribbean Freedom), offered in Winter 2023', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('JGE321H1', 'Multicultural Perspectives on Environmental Management', '24L', 'Diverse approaches to environmental issues in a variety of multicultural settings are introduced, compared and analyzed, using case studies. Perspectives on environmental management will be discussed as they emerge from contexts such as Latin America, Asia, or Africa.', 'ENV321Y1', 3, '{"operator": "OR", "items": ["ENV221H1", "ENV222H1", "GGR222H1", "GGR223H1"]}'::jsonb),
    ('JGE331H1', 'Resource and Environmental Theory', '24L', 'Introduction to and critical evaluation of major ideas and conceptual traditions underpinning environmental and natural resource politics and regulation. Topics include: parks and protected areas, market-based environmental regulation, property rights and conservation, Malthusianism, and biodiversity conservation. Emphasis is placed on critical reading of primary texts.', null, 3, '{"operator": "OR", "items": ["GGR100H1", "JEG100H1", "GGR107H1", "ENV221H1", "ENV222H1", "GGR222H1", "GGR223H1"]}'::jsonb),
    ('JGE481H1', 'Field Course in Environmental Geography', null, 'Introduction to field studies in environmental geography. The course may include individual assignments and group work. Field trips are concentrated during a one-week period in late August or early September. Some preparation during the preceding summer may be required. Periodic course meetings and shorter field trips continue, along with course work, during the Fall Term. Each student is required to pay the costs of their transportation and accommodation (field trip costs: $107). Students must submit an application directly to the Department in the spring (see the Geography website for details in March). Course may be limited by size. Not eligible for CR/NCR option.', 'GGR481H1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('JGJ360H1', 'Holocaust in Literature (E)', '24S', 'This course examines literary works written in different languages, in ghettos and concentration camps during the Holocaust, as well as those reflecting on the genocide in its aftermath. We focus on literature as a means of engaging with the unimaginable and on the cross analysis of eye-witness and memory writing.', 'CJS220H1,  GER367H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JGU216H1', 'Globalization and Urban Change', '24L', 'Focusing on the impacts that global flows of ideas, culture, people, goods, and capital have on cities throughout the globe, this course explores some of the factors that differentiate the experiences of globalization and urban change in cities at different moments in history and in various geographic locations.', 'JGI216H1', 3, null::jsonb),
    ('JGU346H1', 'The Urban Planning Process', '24L', 'Overview of how planning tools and practice shape the built form of cities. This course introduces twentieth century physical planning within its historical, social, legal, and political contexts. Community and urban design issues are addressed at local and regional scales and in both central cities and suburbs. The focus is on Toronto and the Canadian experience, with comparative examples from other countries, primarily the United States. Transportation costs: $20.', 'JGI346H1,  GGR361H5', 3, null::jsonb),
    ('JGU454H1', 'The Role of the Planner: Making a Difference', '24L', 'Focuses on the role of a planning practitioner in contemporary society using a wealth of examples drawn from recent issues and debates in Canadian cities and regions. The course will walk students through the demands made of planners in terms of both technical expertise as well as political necessity and ask them to think actively about how to prepare for the extraordinary growth of cities during the next century. Examples of issues that will be discussed in some detail include the myths surrounding the city vs. the suburbs, the creativity and passion involved in planning work and the need to see Toronto''s future from a regional perspective.', 'JGI454H1', 3, '{"operator": "AND", "items": [{"credits": 14.5, "department": null}]}'::jsonb),
    ('JHA384H1', 'Japan in the World, Mid-16th to Mid-20th century', '24L', 'This course examines Japan within the context of world history from the mid-16th to the mid-20th century. Rather than seek comprehensive coverage of Japan''s national history along a linear timeline, we will use Japan as a lens through which to consider key moments in the history of the modern world.', null, 3, '{"operator": "OR", "items": ["HIS102Y1", "HIS103Y1", "HIS107Y1", "HIS241H1", "HIS242H1", "HIS244H1", "HIS250H1", "HIS250Y1", "HIS271Y1", "HIS280Y1", "HIS281Y1", "HIS282Y1", "HIS283Y1", "HIS291H1", "HIS291Y1", "HIS292H1", "HIS292Y1", "HIS297Y1", {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('JHA394H1', 'The Asia Pacific War', '24L', 'This course examines the Second World War in the Asia Pacific region and highlights: (1) how imperialism and colonialism of both the Euro-American and Japanese varieties were central to the War''s outbreak, conduct, and “resolution”; (2) various “local” rather than simply national experiences and memories of the War, including those of marginalized groups in Japan and its colonies, “comfort women,” victims of war atrocities, Asian North Americans, African Americans, and Pacific Islanders.', null, 3, '{"operator": "OR", "items": ["HIS107Y1", "HIS242H1", "HIS250H1", "HIS251H1", "HIS263Y1", "HIS271Y1", "HIS280Y1", "HIS281Y1", "HIS282Y1", "HIS283Y1", "HIS284Y1", "HIS292Y1", "HIS311Y1", "HIS317H1", "HIS328H1", "HIS338H1", "HIS343H1", "HIS343Y1", "HIS344H1", "HIS344Y1", "HIS351Y1", "HIS361Y1", "HIS377H1", "HIS385H1", "HIS385Y1", {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('JHA410H1', 'Clinical Neuroimaging', '24L/12T', 'This course focuses on the use of neuroimaging techniques in understanding how trauma, disorders, and disease impact neural structure and function. Lectures will focus on introduction to techniques and clinical/research applications. Lab work will focus on the development of practical skills including image processing, analyses, and experimental design.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "PSL300H1", {"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB200H1", "PSY290H1", "ANA300Y1"]}]}'::jsonb),
    ('JHE353H1', 'History of Evolutionary Biology', '24L/10T', 'A historical examination of major ideas about biological evolution, with an emphasis on the period from the 18th century to the 1950s, and of their impact on scientific and social thought. Topics include the diversity of life and its classification, the adaptation of organisms to their environments, Wallace''s and Darwin''s views on evolution by natural selection, sexual selection, concepts and mechanisms of biological inheritance, and the implications of evolutionary theory for the organization of human society.', 'HPS353H1', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 0.5, "department": null}]}'::jsonb),
    ('JHE355H1', 'History and Philosophy of Evolutionary Biology', '24L/10T', 'An examination of the place of the organism in evolutionary theory from the early 1900s to the present. Biology is the science of living things, and yet, paradoxically, living things--organisms--have been comprehensively left out of the Modern Synthesis theory of evolution that developed in the twentieth century. This course surveys the reasons--historical, philosophical and empirical--for the marginalization of organisms from evolutionary theory. It examines the ways in which evolutionary developmental biology attempts to restore the organisms to a central place in evolutionary biology. Offered by faculty in the Institute for the History and Philosophy of Science and Technology.', null, 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('JHM307H1', 'Islamic Legal History: Formation and Encounters', '24L', 'This course examines the formation and encounters of Islamic Law with Legal Others from roughly the 8th century CE to the early formation of the Ottoman Empire. The Islamic legal tradition arose in a complex historical context in which legal traditions mapped onto, and gave legal cover to, imperial polities. As the Islamic polity expanded, so too did the imagination of jurists having to contend with new realities (political, geographic, economic, and otherwise). This course will introduce students to the formation of Islamic law in a context of contending legal orders, its ongoing encounters with legal orders in the course of Islamic expansion, and the retraction of Islamic legal orders and institutions as a tradition that anticipated political sovereignty experienced the limits of that sovereignty. Examples will be drawn from the Middle East, Africa, South Asia, and South East Asia. The course will introduce students to the disciplinary focus of Law and History through a focus on doctrine, institution, and the implications on both as territory and people are subject to varying waves of imperial designs and local resistance.', null, 3, '{"operator": "AND", "items": ["HIS268H1"]}'::jsonb),
    ('JHN323H1', 'Indigeneity in the Caribbean', '24L', 'Explores the legacies of the pre-Columbian era, as well as the post-1492 experiences of people of pre-Columbian Caribbean ancestry. Examines the origins and consequences of the Caribbean''s narrative of "indigenous absence", as well as the relationship between indigeneity, globalization and diaspora.', null, 3, '{"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}, "HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('JHU473H1', 'Environmental Crises, Human Mobility, and Health', '24S', 'Multiple environmental crises – climate change, environmental degradation, loss of biodiversity, resource depletion – are already affecting every inhabited region of the globe, impacting human health in direct, indirect, and systemic ways. At the systemic level, they act as risk multipliers, compounding the effects of pre-existing social and political determinants of health, including human mobility. This course discusses the interactions between environmental crises and human mobility, and their impact on human health.', null, 3, '{"operator": "OR", "items": ["HST209H1", "HMB203H1", "HMB303H1"]}'::jsonb),
    ('JIA400H1', 'Interdisciplinary Practice for the Arts', '72P', 'While examining the interconnectedness of the arts, students are required to meet between sessions and develop projects connected to their study. These projects involve a range of media, including theatre, film, music and visual art (installation). An application, a proposal, and/or an interview are required in order to be considered for enrollment in this course. Please consult the CDTPS Application Guidelines for specific procedures and deadlines.', null, 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('JIG322H1', 'Indigenous Worlds, Worldviews and the Environment', '24L', 'Explores the diverse ways of understanding and responding to the world that emerge from indigenous cultures around the world. Examines how indigenous ways of being and relating to their natural environment can help us understand and address the current environmental crisis. Using examples of indigenous activism from Canada and around the world, examines how colonial histories shape dispossession and marginalization and inform visions for the future. Topics include traditional ecological knowledge, place-based social movements, environmental concerns of indigenous peoples, bio-cultural restoration and decolonization of nature-human relations.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["INS200H1", {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, "INS250H1", "GGR107H1", "GGR124H1", "GGR240H1", "GGR246H1", "GGR254H1"]}]}'::jsonb),
    ('JIG440H1', 'Indigenous Geographies', '36S', 'This course draws on theoretical texts of Indigeneity, with a primary focus on Indigenous spaces in the Americas. Course participants will examine how core geographic concepts such as place, territory, land, movement and the scale of the body are sites of colonial dispossession and violence, as well as sites for decolonial and liberatory thought and practice. We will primarily engage with Indigenous-led scholarship within Geography and Indigenous Studies, and creative forms of knowledge production generated across Indigenous communities.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["INS200H1", {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}, "INS250H1", "GGR107H1", "GGR124H1", "GGR240H1", "GGR246H1", "GGR254H1"]}]}'::jsonb),
    ('JIH366H1', 'Indigenous Histories of the Great Lakes, 1815 to the Present', '24L', 'Explores the history of Aboriginal peoples (Indigenous and Metis) living in the Great Lakes Region after the Great Lakes were effectively split between British North America (later Canada) to the north and the united States to the south, when a rapidly increasing newcomer population on both sides of the border marginalized Indigenous peoples and settled on their land. Topics include a comparative examination of Indigenous experiences of colonialism, including treaties and land surrenders as well as the development of government policies aimed at removing and/or assimilating Great Lakes peoples. This course will also study resistance by First National and Tribal Councils to those programs over nearly two centuries and assess local strategies used for economic and cultural survival.', 'HIS366H1/  HIS369Y1', 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1", "HIS271Y1", "INS200H1", "INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}'::jsonb),
    ('JIH369H1', 'Great Lakes Indigenous Histories to 1830', '24L', 'Explores the history of Aboriginal Peoples (Indigenous and Métis) living in the Great Lakes Region from the 16th century to the aftermath of the War of 1812. Weaving together interdisciplinary sources, this course examines central events in Great Lakes history including the formation of the Wendat and Haudenosaunee Confederacies and key Anishinabek alliances, the arrival of European newcomers into an Indigenous landscape, the social-political impact of new diseases, reactions to European missionaries, the fur trade, major conflicts and peace processes including the Great Peace of Montreal, the Treaty of Niagara and the 60 Years War for the Great Lakes; and ending with the period of significant encroachment of new settlers on Indigenous lands.', 'HIS369H1/  HIS369Y1', 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1", "HIS271Y1", "INS200H1", "INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}'::jsonb),
    ('JIH460H1', 'Indigenous Histories of North America', '24S', 'This senior seminar takes a regional approach, featuring work written by or in collaboration with Indigenous scholars and Indigenous communities, to draw students into discussion of comparative historiographies, the role of worldview in historical writing and the significant methodological interventions made by Indigenous Studies. Students explore oral history and material culture as sources for writing history and discuss ethical research practices for community-based scholarship. In addition to active participation, each student will write a major paper, approximately 15 pages in length, in the form of a review essay on the historiography of either a region or a topic. This course is a joint graduate/undergraduate seminar.', null, 3, '{"operator": "OR", "items": ["INS200H1", "INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}, "INS205H1", "HIS230H1", "HIS366H1", "HIS369H1"]}'::jsonb),
    ('JJH370H1', 'Soviet Jewish History, Culture, and Diaspora', '24L', 'The course examines history, culture and diaspora of Russian-speaking Jews in the 20th and 21st century. We will discuss how Jews experienced Russian Revolutions of 1917, Stalinism, Soviet Great Terror of 1937, World War II and the Holocaust, post-war challenges, the “Thaw” of the 1960s, “Stagnation of the 1980s”, Dissident movement, Perestroika, collapse of the Soviet Union and the development of post-Soviet diasporas. We will read works by both Soviet Jewish authors, including Vassily Grossman, Shira Gorshman, Isaac Babel, Rivka Levin and post-Soviet ones, such as David Bezmozgis, Lara Vapnyar and Boris Fishman, study artifacts of anti-religious propaganda such as Red Passover Celebration scripts, discuss oral histories of Soviet Jews, read scripts of Yiddish theater performances (in English translation), and scrutinize (and maybe even try) recipes of Soviet Jewish food. No prior knowledge is required, but if you took a course on European history or Jewish history, it will be an asset.', 'CJS391H1 (Soviet Jewish History, Culture, and Diaspora), offered in Fall 2024.', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JLN327H1', 'Culture and Modernity in the Hispanic Caribbean', '24L', 'Explores the Hispanic areas of the Caribbean including the Caribbean areas of continental Spanish-speaking America. Topics may include: regional politics, state and economy; revolutions and authoritarian regimes; popular culture, the arts and media; religion and society; gender and sexuality; state structures; diasporas and migration.', null, 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1", "LAS200H1", "LAS201H1"]}'::jsonb),
    ('JLN427H1', 'Advanced Topics: The Hispanic Caribbean', '24S', 'Explores, in depth, a country in the Hispanic Caribbean or a theme relating to the Hispanic Caribbean. Topics vary each year and may include: Cuban society; Hispanic Caribbean revolutions; Hispanic Caribbean music, art and popular cultures; Hispanic Caribbean diasporas.', 'NEW427H1', 3, '{"operator": "OR", "items": ["HIS230H1", "HIS231H1", "JLN327H1", "LAS200H1", "LAS201H1", "CAR120Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1"]}'::jsonb),
    ('JLP315H1', 'Language Acquisition', '36L', 'Infants'' abilities at birth, prelinguistic development, the first words, phonological, syntactic and semantic development. Social variables influencing language acquisition, bilingualism, models of development, language play. (Sponsored by the Departments of Linguistics and Psychology, but administered solely by the Dept. of Linguistics).', 'PSY315H5,  PLIC24H3', 2, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('JLP374H1', 'Psychology of Language', '36L', 'In Psychology of Language, we investigate human and other animal communication, structure of human language, word meaning and semantic memory, psychological studies of syntax, bilingualism, language and thought, language errors and disorders. (Sponsored by the Departments of Linguistics and Psychology, but administered solely by the Dept. of Linguistics).', 'LIN258H5,  PSY374H5,  PLIC55H3', 2, '{"operator": "OR", "items": ["LIN228H1", "LIN229H1", "LIN232H1", "LIN241H1", "PSY260H1", "PSY270H1", "PSY280H1", "PSY290H1", "COG250Y1"]}'::jsonb),
    ('JLP471H1', 'Advanced Psycholinguistics', '24S', 'Seminar in advanced topics in psycholinguistics. Content varies from year to year. (Sponsored by the Departments of Linguistics and Psychology, but administered solely by the Dept. of Linguistics).', null, 2, '{"operator": "AND", "items": ["JLP374H1"]}'::jsonb),
    ('JLS472H1', 'Child Language Disorders', '36L', 'Students are introduced to the etiologies and characteristics of speech and language disorders in children, associated with autism, intellectual disabilities, and specific language impairment. Theoretical underpinnings of the major intervention approaches for children with speech and language disorders are discussed. (Given by the Departments of Linguistics and Speech Language Pathology)', null, 4, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", "LIN228H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('JLS473H1', 'Adult Speech and Language Disorders', '36L', 'Students are introduced to the etiologies and characteristics of speech and language disorders in adults, associated with aphasia, neurodegenerative disorders, and head injuries. The effects of communication handicaps on the individual and theoretical underpinnings of the major intervention approaches for adults are discussed. Given by the Departments of Linguistics and Speech Language Pathology. (Not offered every year)', null, 4, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('JLS475H1', 'Literacy and Reading Disorders', '36L', 'Literacy and Reading Disorders is an introduction to the typical development of emergent literacy skills, including oral language, phonological awareness, narratives, and emergent writing in children; a discussion of the effects of language disorders on emergent literacy skills; a survey of approaches to intervention for children''s emergent literacy skills. Given by the Departments of Linguistics and Speech Language Pathology. (Not offered every year)', null, 4, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('JLS476H1', 'Linguistics in the Workforce: Clinical Practice and Research', '36S', 'This course exposes students to research and practical approaches in the context of health professions of relevance to linguistics students, especially audiology and speech-language pathology. Students learn about evidence-informed practice, research methodologies, practice approaches and theories in the health professions. Students will be poised to benefit from optional service learning placements during or following the course, in research laboratories or clinical settings. Successful completion of this course provides students with exposure and experience of use in their applications to audiology, speech-language pathology, and other clinical programs and in their future health or graduate studies. Not eligible for CR/NCR option. (Not offered every year).', null, 4, '{"operator": "AND", "items": ["LIN101H1", "LIN102H1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('JMH385H1', 'Islamic Law and the Modern State', '24L', 'What happens to the shariʿa when it is applied by modern nation-states? This course introduces students to the way states, with Muslim majorities and minorities, from Canada to Malaysia, passing by Nigeria, Palestine, Iran, and Pakistan approach, accommodate, or apply Islamic law. We also discuss the way Muslims, lay and scholarly, talk about, practice, and follow Islamic law under modern states. Based on an examination of law in practice, we will be able to theorize modern transformations of the shariʿa and provincialize the modern state and its legal regime.', null, 2, '{"operator": "OR", "items": ["NMC103H1", "RLG204H1"]}'::jsonb),
    ('JNR301H1', 'The History of Buddhist Meditation', '36L', 'This course will survey historical, cultural, and textual contexts for Buddhist meditative and contemplative practices and techniques.', null, 2, '{"operator": "OR", "items": ["RLG206H1", "NEW232Y1", "BPM232H1"]}'::jsonb),
    ('JNS450H1', 'Sexuality & Disability', '24S', 'An interdisciplinary and intersectional approach to the study of disability and sexuality. Students will engage with historical, mainstream and critical discourses and explore complex issues and representations pertaining to disability, sexuality, sexual practices and desire. Draws from a range of writings and cultural texts in queer, crip and sexuality studies.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": "SDS"}, "NEW240Y1", "NEW240H1", "CSE240H1", "NEW241Y1", "CSE241Y1"]}'::jsonb),
    ('JPA331H1', 'Rise of China as a Global Power', '24L', 'This course will take students through important domestic institutions and events in China that shape its current political landscape. Students will be prompted to think about the implications of domestic political factors for China''s rise as a global power. The course examines major China''s adventurism abroad, such as the Belt-and-Road Initiative, and what increasing footprints of Chinese state and private firms overseas mean for international politics. (Given by the Department of Political Science and the Contemporary Asian Studies Program)', 'JPA331Y1/ POLC16H3', 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": null}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('JPA331Y0', 'Rise of China as a Global Power', '48L', 'This course will take students through important domestic institutions and events in China that shape its current political landscape. Students will be prompted to think about the implications of domestic political factors for China''s rise as a global power. The course examines major China''s adventurism abroad, such as the Belt-and-Road Initiative, and what increasing footprints of Chinese state and private firms overseas mean for international politics. (Offered as part of the Summer Abroad program) (Given by the Department of Political Science and the Contemporary Asian Studies Program)', 'JPA331H1/ JPA331Y1/ POLC16H3', 3, '{"operator": "OR", "items": [{"credits": 2.0, "department": "POL"}, {"credits": 1.0, "department": "CAS"}]}'::jsonb),
    ('JPA376Y0', 'Transforming Global Politics: Comparative and Chinese Perspectives', '48L', 'Set against the backdrop of the rise of China, this course examines the dynamics of global change from comparative and Chinese perspectives. Themes include international security, political economy, political development and democracy, global climate change, economic development, poverty and inequality, corruption, technology innovation, among others. (Given by the Department of Political Science and the Contemporary Asian Studies Program)', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5", "POL224H1", "POL224Y1", "CAS200Y1"]}'::jsonb),
    ('JPA453H1', 'Authoritarianism in Comparative Perspective', '24S', 'This course examines the politics of authoritarianism in theory and practice. It covers major theories in authoritarian politics, ranging from selectorate theory, authoritarian institutions, impact of institutions on political outcome, ways of measuring authoritarian state power, democracy and development, to social movement and state repression in authoritarian regime, and political transitions. On empirical application, we will draw on cases from around the world, with some emphasis on Asian authoritarian states. (Given by the Department of Political Science and the Contemporary Asian Studies Program)', 'POL453H1', 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('JPE395H1', 'Physics of the Earth', '24L', 'Designed for students interested in the physics of the Earth and the planets. Study of the Earth as a unified dynamic system; determination of major internal divisions in the planet; development and evolution of the Earth''s large scale surface features through plate tectonics; the age and thermal history of the planet; Earth''s gravitational field and the concept of isostasy; mantle rheology and convection; Earth tides; geodetic measurement techniques, in particular modern space-based techniques.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY132H1", "PHY152H1", "PHY180H1", "MIE100H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT291H1", "AER210H1"]}, {"operator": "OR", "items": ["PHY254H1", "PHY293H1", "MAT244H1", "MAT267H1", "MAT290H1", "MAT292H1"]}]}'::jsonb),
    ('JPE493H1', 'Seismology', '24L', 'Why do earthquakes occur and how are they related to tectonic motion of the Earth''s surface? What is the physics behind the propagation of seismic waves through the Earth, and how can it be used to determine the internal structures of the Earth? This introductory course is aimed at understanding the physics behind seismic wave propagation, as well as asymptotic and numerical solutions to the elastodynamic equation. Travel time and amplitude of seismic waves are discussed based on seismic ray theory, while numerical methods are introduced to obtain accurate solutions to more complex velocity structures. Seismic tomographic methods, including their applications to hydrocarbon reservoir imaging, are also covered.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["JPE395H1", "JGA305H1"]}, {"operator": "OR", "items": ["MAT244H1", "MAT267H1"]}]}'::jsonb),
    ('JPF455H1', 'Conceptualizing Cities in a Global Context', '24S', 'With over half of the population on this planet being urban, the significance of improving our understanding of cities in a global context has never been greater. This course is designed to improve awareness of cities as approached by different disciplines and in different international contexts. (Given by the Department of Political Science and the Faculty of Architecture, Landscape, and Design)', 'JPF455Y1', 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1"]}'::jsonb),
    ('JPF456H1', 'Global Cities – Core Issues and Challenges', '24S', 'The core issues confronting city leaders across the globe are examined in comparative perspective and in a context of shifting global agendas. The study of cities of Latin America, Asia and Africa, are brought together in comparative context with the study of cities of Europe and North America. (Given by the Department of Political Science and the Faculty of Architecture, Landscape, and Design)', 'JPF455Y1', 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1"]}'::jsonb),
    ('JPH311H1', 'From Universal Gravity to Quantum Information: The Making of Modern Physics', '24L', 'Topics in the history of physics from antiquity to the 20th century, including Aristotelian physics, Galileo, Descartes, electromagnetism, thermodynamics, statistical mechanics, relativity, quantum physics, and particle physics. The development of theories in their intellectual and cultural contexts.', null, 5, '{"operator": "AND", "items": [{"credits": 0.5, "department": "PHY"}]}'::jsonb),
    ('JPH441H1', 'Physical Science in Contemporary Society', '24L', 'This course will discuss the complex, real-life, ethical, and philosophical issues behind how science gets done, including questions such as how we as scientists strive to determine the truth; who determines what science is done, and on what basis; how we as a community manage science and make decisions about education, authorship, publication, hiring, et cetera (including issues related to equity, inclusivity, and diversity); and how we as a society fund science and apply its discoveries.', null, 3, '{"operator": "OR", "items": ["PHY224H1", "PHY250H1", "PHY252H1", "PHY254H1", "PHY256H1"]}'::jsonb),
    ('JPI201H1', 'Indigenous Politics in Canada', '24L/12T', 'This course explores key issues in Indigenous politics in Canada. Provides students with an overview of historical and contemporary socio-political issues in Indigenous societies and institutions such as Indigenous self-governance, land claims and treaty negotiations.', 'POL308H1/  POLC56H3', 1, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["INS201Y1", {"operator": "AND", "items": ["INS201H1", "INS202H1"]}]}]}'::jsonb),
    ('JPM300H1', 'Research Readiness and Advancing Biomedical Discoveries', '12L/24T', 'Explore how scientists leverage their knowledge and skills to advance academic biomedical discoveries from the laboratory to improve patient health through either commercialization or not-for-profit approaches. Students will learn about innovation and develop key research and industry skills including intellectual property, ethics, budget and project management; learn how to critically evaluate scientific evidence and effectively communicate to a wide audience. This hybrid student-centered course will include interactive online modules and in-class group work. Course work will focus on developing skills and knowledge to help you be successful in diverse research courses and future careers. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["BCH210H1", "BCH242Y1", {"operator": "AND", "items": ["CHM361H5", "CHM362H5"]}]}]}'::jsonb),
    ('JPM400Y1', 'Biomedical Incubator Capstone Project', '240P/16S', 'Discover what it is like to be part of a biomedical innovation team. Develop and engage in biomedical research in a simulated small business/incubator setting under the guidance of a faculty mentor. Bring your proposed  JPM300H1 project to life, while acquiring budget management, research, business and communication workplace skills for future careers. Enrolment is application-based. Application requirements and process are presented as part of the  JPM300H1 course. Proposals will be reviewed by committee and successful proposals will be matched to a mentor. Not eligible for CR/NCR option. Application required; contact department (undergrad.pharmtox@utoronto.ca) for more information.  Students will form teams and develop a research proposal based on either: 1. Faculty led concept requiring further development and testing, which would not normally be funded grants and would be tangential to ongoing research in the lab. 2. Student developed innovative idea that requires further development and testing. This should be a project that is not being investigated in a UofT research lab.', null, 4, '{"operator": "AND", "items": ["JPM300H1", {"operator": "OR", "items": ["PCL367H1", "PCL368H1", "PSL372H1", "BCH370H1", "BCH377H1"]}]}'::jsonb),
    ('JPR364H1', 'Religion and Politics in the Nation State', '24L', 'This course will engage with contemporary debates on religion and politics in the context of the nation-state in our post-9/11 world, and will do so comparatively across a wide range of contexts. The emphasis will be on understanding the evolving relationship between religion and politics in liberal democracies, and examining challenges facing democratic politics from the religious sphere, both in the West, where secular liberalism is the dominant framework for discussing these questions, and in Africa, India, and the Middle East, where such a framework is more likely to be contested. The themes explore will include secularization, religious pluralism and tolerance, human rights regimes, the idea of "civil religion," the impact of religion on party politics, the formation of identity and political community, the legal regulation of sometimes-competing claims based on religious faith, gender, and sexuality, and the rise of extremist forms of religious politics, conspiracy thinking, new online communities that lead to dangerous political outcomes, such as ''QAnon'' and ''Plandemic''. Cases studies will include the USA, Canada, France, Turkey, Egypt, Nigeria. (Given by the Departments of Political Science and Religion)', 'JPR364Y1', 2, '{"operator": "OR", "items": [{"credits": 0.5, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('JPR365H1', 'Global Religion and Politics', '24L', 'This course will engage with contemporary debates on religion and politics in the international context in our post-9/11 world, and will do so comparatively across a wide range of contexts. The emphasis will be on understanding the evolving role transnational religion has played in the past three decades, where new global networks have emerged as central global actors. We will focus empirically on the rise of radical reformist Islam and evangelical Christianity, the two most dramatically successful forms of religiosity around the world today. We will study the implications for the foreign policies of key nation-states, as well as the forces that have contributed to the prevalence of contestatory religious politics and networks as new and poorly understood global actors. International religious freedom, human rights, the role of media and mediation, the place of religious or theological doctrines or imaginaries in constructing and motivating a range of political goals, many involving the use of violence. We will focus as well on the global spread of extremist forms of religious politics, conspiracy thinking, new online communities that lead to dangerous political outcomes, such as ''QAnon'' and ''Plandemic''. Many of the cases will focus on the non-Western world, especially the Middle East and Africa.(Given by the Departments of Political Science and Religion)', 'JPR364Y1', 2, '{"operator": "OR", "items": [{"credits": 0.5, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('JPR374H1', 'Religion and Power in the Postcolony', '24L', 'This course examines the role of a variety of religious forms and spiritual practices in the politics of postcolonial societies, tracing their genealogies from the colonial period to the present. Cases taken principally from Africa and Asia. (Given by the Departments of Political Science and Religion)', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}, {"credits": 1.5, "department": "RLG"}]}'::jsonb),
    ('JPR419H1', 'Secularism and Religion', '24S', 'Themes considered include what notion of religion is necessary for secular governance, and how secularity relates to particular discourses of citizenship and practices of political rule. Case studies include the effects of colonial rule on religious life; Jewish emancipation in Europe; and religious freedom in France and North America. (Given by the Departments of Political Science and Religion)', 'RLG419H1', 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('JPR458H1', 'Postsecular Political Thought: Religion, Radicalism and the Limits of Liberalism', '24S', 'The course will examine debates on postsecularism and religion''s public, political role as articulated by political thinkers such as Jurgen Habermas, by focusing on politically radical or revolutionary challenges to liberalism in the 20th and 21st century, especially from the postcolonial world, whose theoretical arguments are grounded upon or draw their inspiration from religious traditions, doctrines and practices.', null, 2, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('JPR459H1', 'Fanaticism: A Political History', '24S', 'This seminar in theory will explore the modern history of the concept of ''fanaticism'' and its role in the development of political modernity. A focus on the concept of the "fanatic" (and its cognates) from the perspective of its various uses in political and religious thought from the Early Modern period through the Enlightenment and up to the present day, provides a fascinating opportunity for a critical review of the secular, rationalist, and scientific assumptions underwriting modern political forms and concepts, especially those of liberal democracy. At the same time, the course will offer critical insight into the ways in which religious and political differences among colonial "others" were, and continue to be, central to the elaboration of Western theoretical discourse on fanaticism and extremism as forms of "political pathology". (Given by the Departments of Political Science and Religion)', null, 2, '{"operator": "OR", "items": [{"operator": "AND", "items": [{"credits": 2.0, "department": null}, {"credits": 1.0, "department": null}]}, {"operator": "AND", "items": [{"credits": 0.5, "department": null}, {"credits": 1.0, "department": null}]}]}'::jsonb),
    ('JPS315H1', 'LGBTQ Politics', '24L', 'This is an interdisciplinary course examining the development of the Lesbian, Gay, Bisexual, Transgender and Queer (LGBTQ) movement and its interaction with the state in the US and Canada. (Given by the Department of Political Science and the Sexual Diversity Studies Program)', 'JPU315H1', 3, '{"operator": "OR", "items": ["SDS255H1", "SDS256H1", "UNI255H1", "UNI256H1", {"credits": 1.0, "department": null}, {"credits": 1.0, "department": null}]}'::jsonb),
    ('JPS316H1', 'Indigenous Feminist and Queer Theories', '24L', 'This course explores Indigenous feminist and queer political thought. We survey comparative political theories developed by scholars in the field of Indigenous, gender, and feminist studies. Charting key developments in the field, the course investigates unique and innovative ideas about affect, decolonization, erotics, utopia, and much more. (Given by the Department of Political Science and the Sexual Diversity Studies Program)', 'POL377H1 Topics in Comparative Politics I (Indigenous Feminist and Queer Theories) taken in Winter 2020 (LEC0101), Winter 2021 (LEC0101), Winter 2022 (LEC0201)', 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}, {"operator": "AND", "items": [{"credits": 0.5, "department": null}, {"credits": 0.5, "department": "SDS"}]}]}'::jsonb),
    ('JPS378H1', 'Sex and the State', '24L', 'What role have sex and sexuality played in the formation of the modern nation State? How has the State regulated sex? This course explores these questions with a theoretical focus on biopolitics. We will proceed in two parts. First, we engage Foucault''s History of Sexuality and its reception by postcolonial theorists, focusing on questions of state building. The second part of the course shifts examination from State formation to contemporary forms of sexual regulation by the State. This includes maintenance of the public/private divide, citizenship law and nationalism, administrative violence and the prison industrial complex, and neoliberalism and BDSM. By the end of the course, students are able to apply core theoretical concepts and identify forms of contemporary sexual regulation in a variety of Western and non-Western contexts. (Given by the Department of Political Science and the Mark S. Bonham Centre for Sexual Diversity Studies.)', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('JQR360H1', 'The Canadian Census: Populations, Migrations and Demographics', '24L/12T', 'Examines the Canadian population census through the experience of diasporic groups in Canada. Approaches the census as a statistical tool, an historical source and an ideological project of citizenship and nationalism. Uses census data to explore mathematical and statistical concepts and to integrate numerical ways of thinking with qualitative analysis. (Jointly sponsored by African Studies, Diaspora and Transnational Studies, Caribbean Studies, Critical Studies in Equity and Solidarity, and Latin American Studies).', null, 3, '{"operator": "OR", "items": ["DTS200H1", "DTS200Y1", "HIS230H1", "HIS231H1", "LAS200H1", "LAS201H1", "CAR120Y1", "AFR150Y1", "CAR220H1", "CAR221H1", "NEW224Y1", "CAR225H1", "CAR226H1", "CSE240H1", "NEW240Y1"]}'::jsonb),
    ('JRA401H1', 'Topics in Comparative Politics V', '24S', 'Selected issues in comparative politics. Content and instructor vary from year to year. (Given by the Department of Political Science and the Centre for European and Eurasian Studies)', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('JRA402H1', 'Topics in Comparative Politics VI', '24S', 'Selected issues in comparative politics. Content and instructor vary from year to year. (Given by the Department of Political Science and the Centre for European and Eurasian Studies)', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('JRC199H1', 'Truths & Reconciliations in Canada', '24S', 'In this course, we examine the idea of reconciliation among Indigenous and Canadian nations by considering the complicated role of religion and spirituality in "truth and reconciliation." Specifically, residential schools for Indigenous children were a collaboration of church and state that violently broke the spirit and intent of the treaties—or sacred promises—made between the Crown and Indigenous nations. The course will set the 2015 Truth & Reconciliation Commission of Canada in a longer history of twentieth-century commissions, reports, and petitions in which both Indigenous and Canadian people (and some churches) named the cultural and spiritual genocide of residential schools and called for action. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('JRN199H1', 'Exodus and Enslavement', '24S', 'Popular conceptions of enslavement in North America have influenced how we frequently imagine enslavement in Exodus and related biblical and related texts from the ancient Near East. Yet, depictions of enslavement in these ancient texts may be strikingly different from our ideas of enslavement in North America. This course explores similarities and differences between enslavement in these different historical contexts. It also examines how biblical texts were utilized in debates over and revolts against enslavement primarily in the eighteenth and nineteenth century. All readings will be in English. No knowledge of Hebrew is required. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('JRN301H1', 'Disability in the Hebrew Bible and Related Texts', '24L', 'The Hebrew Bible (sometimes called the Old Testament) has influenced ideas about disability in societies across the globe for thousands of years. Yet, notions of disability in the Hebrew Bible may be strikingly different from what we might imagine. This course explores how some biblical texts and related ancient literature conceptualize disability in relation to issues of ethnicity, sexuality, beauty, age, social class, religious expression and so on. We will examine a number of these issues both in their ancient context and in some more recent interpretations of the Hebrew Bible. All readings will be in English. No knowledge of Hebrew is required.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JSC270H1', 'Data Science I', '24L/24P', 'This course is restricted to students in the Data Science Specialist program. Data exploration and preparation; data visualization and presentation; and computing with data will be introduced. Professional skills, such as oral and written communication, and ethical skills for data science will be introduced. Data science workflows will be integrated throughout the course. These topics will be explored through case studies and collaboration with researchers in other fields.', null, 5, '{"operator": "AND", "items": ["STA257H1", "CSC207H1"]}'::jsonb),
    ('JSC301H1', 'Principles and Practices in Science Education', '24L', 'Fundamental principles and practices in education and public outreach in the sciences, mathematics, and engineering, including education research, curriculum, teaching, and assessment.  Students will learn and apply effective strategies which engage and educate learners at the K-16 and public level.  The course assignments include a project and/or placement experience.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('JSC370H1', 'Data Science II', '24L/24P', 'This course is restricted to students in the Data Science Specialist program. Students will learn to identify and answer questions through the application of exploratory data analysis, data visualization, statistical methods or machine learning algorithms to complex data. Software development for data science and reproducible workflows. Communication of statistical information at various technical levels, ethical practice of data analysis and software development, and teamwork skills. Topics will be explored through case studies and collaboration with researchers in other fields.', null, 5, '{"operator": "AND", "items": ["JSC270H1", "STA261H1", {"operator": "OR", "items": ["MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["CSC263H1", "CSC265H1", "CSC263H5"]}, "STA302H1", {"operator": "OR", "items": ["CSC343H1", "CSC343H5"]}]}'::jsonb),
    ('JSC470H1', 'Data Science III', '24L/24P', 'This course is restricted to students in the Data Science Specialist program. Research topics and applications of data science methods will be explored through case studies and collaboration with researchers in other fields. Data analysis, visualization, and communication of statistical information at various technical levels, ethical practice of data analysis and software development, and teamwork skills.', 'STA490Y1', 5, '{"operator": "AND", "items": ["JSC370H1", {"operator": "OR", "items": ["STA314H1", "CSC311H1"]}, {"operator": "OR", "items": ["STA303H1", "STA305H1"]}]}'::jsonb),
    ('JSH300H1', 'Literature and History in Russia', '24L', 'History and Literature were always interconnected in Russia. Writers not only sought to reflect the society around them, but were themselves often social critics and political figures. The course examines key texts in Russian literary tradition both as works of art and as primary sources for the historian. All readings in English.', null, 1, null::jsonb),
    ('JSM354H1', 'Stone Books to Sky Books: The Book as Institution, Commerce and Art', '24L', 'Evolution of the book and printed media in Central and Eastern Europe: legends (and forgeries) of ancient letters, mediaeval illuminated manuscripts, forbidden and "supernatural" books, hand-written and painted books of modernist and avant-garde artists, books as a way of living and dying. Readings in English.', 'SLA254H1', 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JSR312H1', 'Queer Religion and Religiosities', '24L', 'This course will introduce students to key terms, theories, and debates in Queer and Religious Studies and to the history of queer identities as they are expressed within various religious traditions, texts, and communities. It asks how dominant heteronormative discourses on gender and sexuality are adhered to, legitimized, negotiated, and contested within various religious traditions. The course will also allow students to interrogate how power and power relationships are shaped by sex, gender, sexuality, race, ethnicity, class, age, and ability in the world of religion.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": [{"credits": 0.5, "department": "SDS"}, {"credits": 0.5, "department": "RLG"}]}]}'::jsonb),
    ('JSU237H1', 'Introduction to HIV/AIDS: Health, Sexuality and Gender', '36L', 'A critical examination of the HIV/AIDS global pandemic from a multidisciplinary perspective and with an emphasis on sexuality. The course examines the basic biology of HIV/AIDS and then covers social, historical, political, cultural, gender, and public health aspects of HIV/AIDS. Attention is given to the distinct features of vulnerable and marginalized populations, prevention, treatment, drug development, and access to medicines.  JSU237H1 is particularly intended for students in the Health Studies and/or Sexual Diversity Studies programs.', null, 3, null::jsonb),
    ('JSU325H1', 'Queerly Canadian', '36L', 'This course focuses on Canadian literary and artistic productions that challenge prevailing notions of nationality and sexuality, exploring not only how artists struggle with that ongoing Canadian thematic of being and belonging, but also celebrate pleasure and desire as a way of imagining and articulating an alternative national politics.', null, 1, '{"operator": "OR", "items": ["SDS255H1", "SDS256H1", "CDN267H1", "CDN268H1"]}'::jsonb),
    ('JUG320H1', 'The Canadian Wilderness', '24L', 'The idea of wilderness permeates narratives of Canadian national identity, while policy-makers seek to manage and contain natural areas. This course compares and contrasts historical and contemporary wilderness narratives in literature, painting and film with policies in areas such as conservation, urban planning, land claims and tourism.', null, 2, null::jsonb),
    ('JUG325H1', 'Landscapes of Violence in Canada', '24L', 'This course examines how violence is enacted in Canada, at various scales, and across domestic, urban, national, and international landscapes. We will interrogate what is meant by violence; examine its colonial, racial and patriarchal dimensions; explore the impact on people and communities; and attend to forms of resistance and repair.', null, 3, null::jsonb),
    ('JWB318H1', 'The Art of Journalism: Literary Approaches to Reporting', '36S', 'Journalism largely goes unconsidered as a subject for literary analysis, the writing dismissed as formulaic and artless. But from the genre''s inception, there have been writers who approached it as a literary endeavour, committed to not just telling true stories about the world around us but doing so in ways that captivate and engage a reader''s imagination, with all the nuance and precision that literary techniques can afford. In this course, we will read and consider canonical works of journalism from the last 75 years, discussing them as literary works as well as exploring the reporting methods they draw on and the ethical questions they raise. Students will have a choice of assignment tracks, and either develop their own literary reporting projects or write analyses of the works we study.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('JWE206H1', 'Writing English Essays', '24L/12T', 'This course teaches students who already write effectively how to write clear, compelling, research-informed English essays. The course aims to help students recognize the function of grammar and rhetoric, the importance of audience, and the persuasive role of style.', 'JEI206H1', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "ENG"}, {"credits": 4.0, "department": null}]}'::jsonb),
    ('LAS200H1', 'Inventing Latin America: Foundational Themes', '36L', 'An introductory course studying the development of Latin American societies from their pre-Columbian past to the 19th century building of modern nations. Cultural, historical, political, and social topics are examined combining historical documents with art, music and other texts from popular culture.', 'IAS200Y1,  LAS200Y1', 1, null::jsonb),
    ('LAS201H1', 'Defining Latin America: Current Issues', '36L', 'An introductory course studying the development of Latin American societies from the 20th century to the present. Cultural, historical, political, and social topics are examined combining historical documents with art, music and other texts from popular culture.', 'IAS200Y1 and  LAS200Y1', 3, null::jsonb),
    ('LAS300H1', 'Topics in the Social Sciences', '24S', 'The goal of this course is to critically analyze the current economic, social, and political realities of Latin America, based on an insightful knowledge of its past and present. Topics of the course vary depending on the needs of the program and the interests of students.', null, 3, '{"operator": "OR", "items": ["IAS200Y1", "LAS200Y1", {"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}, "POL305Y1"]}'::jsonb),
    ('LAS301H1', 'Topics in the Humanities', '24S', 'The goal of this course is to critically analyze the Latin American social imaginaries as expressed in art, literature and/or film, based on close readings of texts. Topics of the course vary depending on the needs of the program and the interests of students.', null, 1, '{"operator": "OR", "items": ["IAS200Y1", "LAS200Y1", "LAS201H1"]}'::jsonb),
    ('LAS302H1', 'Topics in Latin American Studies', '24S', 'The goal of this course is to critically explore debates and perspectives on development and on the politics of inequality in Latin American contexts. Topics of the course may vary, depending on the needs of the program and the interests of students and instructors.', null, null, null::jsonb),
    ('LAS310H1', 'The Postcolonial Imaginary in Latin America', '24L', 'This seminar style course explores the postcolonial status of Latin America as a controversial issue, through critical analysis of the Latin American social imaginary. The course considers works by Simón Bolívar, José Martí, Ernesto Guevara, Pablo Neruda, Rigoberta Menchú, Subcomandante Marcos, Sergei Eisenstein, Walter Salles, Tomás Gutiérrez Alea, as well as films that illustrate the rich visual culture of the continent. Readings and seminar discussions are conducted in English.', null, 2, '{"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}'::jsonb),
    ('LAS320H1', 'Latin American Thought', '24L', 'This seminar-style course explores critical thinking about culture, history, politics, and society by some of the most influential Latin American intellectuals of the 20th and 21st centuries. Emphasis on theoretical contributions, in English translation, of Latin American thinkers such as Rodó, Vasconcelos, Mariategui, Zea, Dussel, García Canclini, Cornejo Polar, Quijano and Lugones. Topics covered include questing identities, cultural diversity, indigenism, liberation theology, colonialism, neocolonialism, postcolonialism, coloniality, and decoloniality. Readings and seminar discussions in English.', null, 2, '{"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}'::jsonb),
    ('LAS348H1', 'The Renaissance Mexico City', '24S', 'By exploring history, art, architecture, literature and music of sixteenth century Mexico City as a geographical and cultural point of reference, this course explores the historical event known as "the Renaissance" outside of its traditional localities. By the mid 16th century, colonial Mexico City became the contact zone and the hub for the exchange of peoples, goods and ideas that migrated across the Atlantic. Mexico City gives an alternative perspective to how local political and social-historical contexts shape ideas and cultural forms and illustrates the processes and effects of cultural cross-fertilization in the Renaissance. Taught in English.', null, 1, null::jsonb),
    ('LAS350H1', 'Indigenous Realities in Latin America', '24L', 'This course studies the past and present realities of the diverse indigenous societies of the regions we now call Latin America. Eurocentric texts such as the chronicles of the conquest of Mexico, are critically contrasted with diverse indigenous peoples'' self-representing narratives that respond to more than five hundred years of Spanish and Portuguese occupation of their lands. These texts include Nahuatl poetry and accounts of the conquest of Mexico, literary creations from multiple Maya linguistic groups, multi-lingual chronicles from the colonial Inca period, diverse indigenous political manifestos and movements, indigenous testimonios, and decolonizing indigenous literature and criticism. Taught in English.', null, 2, null::jsonb),
    ('LAS370H1', 'Critical Perspectives of Development in Latin American Contexts', '24L', 'A seminar-style course that engages in critical analysis of local and global development initiatives in a Latin American context. The seminar is organized around the interrelated themes of health, economics, education, globalization, and infrastructure. Topics of discussion may include: challenges and ethics of sustainable development initiatives in theory and practice, medical missions and global health, community-based transnational public health projects, developing localities and sustainable economics, local infrastructure development and environmental impacts, ethics and implications of volunteerism, local and global cultural perspectives, the colonial legacies of inequality, dependency and sustainability of development projects. Readings and lectures in English.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('LAS400H1', 'Topics in Latin American Studies', '24S', 'An upper level seminar. Topics of the course vary from year to year, depending on the needs of the program and the interests of students. Offered in alternate years.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["LAS200Y1", {"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}]}, {"operator": "OR", "items": ["LAS300H1", "LAS301H1"]}]}'::jsonb),
    ('LAS401H1', 'Latinos in Canada', '24S', 'A historical survey of migration from Latin American countries to Canada, this course examines mediation strategies of Latinos as they adjust to a new home: negotiation of national identities, political participation, entrepreneurship, cultural representations, and charitable work.', null, 3, '{"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}'::jsonb),
    ('LAS410H1', 'Independent Study', null, 'This course provides an opportunity for students to do academic research related to Latin American issues under the supervision of a faculty member. The intent is that the student, aided and advised by the supervisor, will read relevant literature, and plan, execute, analyze and report on an original and independent investigation of an appropriate topic. For application forms, please visit the "Resources" section of the program''s website. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["LAS200Y1", {"operator": "AND", "items": ["LAS200H1", "LAS201H1"]}]}, {"operator": "OR", "items": ["LAS300H1", "LAS301H1"]}]}'::jsonb),
    ('LAS411Y1', 'Independent Study', null, 'This course provides an opportunity for students to do academic research related to Latin American issues under the supervision of a faculty member. The intent is that the student, aided and advised by the supervisor, will read relevant literature, and plan, execute, analyze and report on an original and independent investigation of an appropriate topic. For application forms, please visit the "Resources" section of the programme''s website. Not eligible for CR/NCR option.', 'LAS410H1', null, '{"operator": "AND", "items": ["LAS200H1", "LAS201H1", {"operator": "OR", "items": ["LAS300H1", "LAS301H1", "LAS302H1"]}]}'::jsonb),
    ('LAT101H1', 'Introductory Latin I', '48S', 'An intensive introduction to Latin for students who have no knowledge of the language; preparation for the reading of Latin literature.', 'LAT100Y1. Students who have studied Latin previously must obtain permission from the Undergraduate Coordinator before enrolling.', 1, null::jsonb),
    ('LAT102H1', 'Introductory Latin II', '48S', 'A continuation of the intensive introduction to Latin in LAT 101H1. Also appropriate for students who have some training in Latin, but have not completed a whole credit course at University or a final-year (Grade 12) course in secondary school.', 'LAT100Y1', 1, '{"operator": "OR", "items": ["LAT101H1"]}'::jsonb),
    ('LAT201H1', 'Intermediate Latin I', '48S', 'Reading of selections of Latin prose works with systematic language study.', null, 1, '{"operator": "OR", "items": ["LAT100Y1", "LAT102H1"]}'::jsonb),
    ('LAT202H1', 'Intermediate Latin II', '48S', 'Continued language training with readings in Latin prose and verse.', null, 1, '{"operator": "OR", "items": ["LAT201H1"]}'::jsonb),
    ('LAT341H1', 'Latin Historians I', '36S', 'Readings from one or more Latin historians.', null, 1, '{"operator": "OR", "items": ["LAT202H1"]}'::jsonb),
    ('LAT342H1', 'Latin Orators I', '36S', 'Readings from Latin orators, including Cicero.', null, 1, '{"operator": "OR", "items": ["LAT202H1"]}'::jsonb),
    ('LAT343H1', 'Latin Prose Authors I', '36S', 'Readings from Latin prose authors (e. g. biography, letters, philosophy).', null, 1, '{"operator": "OR", "items": ["LAT202H1"]}'::jsonb),
    ('LAT350H1', 'Latin Epic I', '36S', 'Readings from one or more Latin epics, including Virgil.', null, 1, '{"operator": "OR", "items": ["LAT202H1"]}'::jsonb),
    ('LAT351H1', 'Latin Drama I', '36S', 'Readings from Latin comedy and/or tragedy.', null, 1, '{"operator": "OR", "items": ["LAT202H1"]}'::jsonb),
